window.__texto({"id": "745541549", "paragrafos": [{"c": "identifica", "t": "CONSULTA PÚBLICA Nº 26, DE 17 DE NOVEMBRO DE 2026"}, {"c": "ementa", "t": "Dispõe sobre a proposta de regulamentação técnica metrológica para instrumentos de pesagem automáticos totalizadores descontínuos."}, {"c": "dou-paragraph", "t": "O PRESIDENTE DO INSTITUTO NACIONAL DE METROLOGIA, QUALIDADE E TECNOLOGIA - Inmetro, no uso das atribuições que lhe conferem a Portaria da Casa Civil nº 1.956, de 7 de março de 2023, e os artigos 4º, § 2º, da Lei nº 5.966, de 11 de dezembro de 1973, e 3º, incisos II e III, da Lei nº 9.933, de 20 de dezembro de 1999, combinado com o disposto nos artigos 18, inciso V, do Anexo I ao Decreto nº 11.221, de 5 de outubro de 2022, e item 4, alínea \"a\" da Resolução nº 8, de 22 de dezembro de 2016, do Conselho Nacional de Metrologia, Normalização e Qualidade Industrial (Conmetro), e tendo como base o processo SEI nº 0052600.006343/2026-60, resolve:"}, {"c": "dou-paragraph", "t": "Art. 1º Fica aberto, a partir da data da publicação desta Consulta Pública no Diário Oficial da União, o prazo de 45 (quarenta e cinco) dias para que sejam apresentadas sugestões e críticas relativas à proposta de Regulamento Técnico Metrológico aplicável aos instrumentos de pesagem automáticos totalizadores descontínuos, fixada no Anexo I."}, {"c": "dou-paragraph", "t": "Art. 2º As críticas e sugestões ao texto proposto deverão ser apresentadas na Plataforma Brasil Participativo, disponível na página eletrônica https://brasilparticipativo.presidencia.gov.br."}, {"c": "dou-paragraph", "t": "§ 1º As críticas e sugestões que não forem apresentadas conforme previsto no caput não serão consideradas como válidas para efeito da consulta pública e serão devolvidas ao demandante."}, {"c": "dou-paragraph", "t": "§ 2º O demandante que tiver dificuldade em utilizar a Plataforma poderá solicitar ajuda através dos canais de atendimento do Inmetro, disponíveis na página eletrônica https://www.gov.br/inmetro/pt-br/canais_atendimento/ouvidoria/faca-sua-manifestacao."}, {"c": "dou-paragraph", "t": "Art. 3º Esta Consulta Pública entra em vigor na data de sua publicação no Diário Oficial da União."}, {"c": "assina", "t": "MARCIO ANDRE OLIVEIRA BRITO"}, {"c": "anexo", "t": "ANEXO IPROPOSTA DE REGULAMENTO TÉCNICO METROLÓGICO"}, {"c": "dou-paragraph", "t": "Portaria Inmetro nº [XXX], de [DIA] de [MÊS] de [ANO]"}, {"c": "ementa", "t": "Aprova a regulamentação técnica metrológica para instrumentos de pesagem automáticos totalizadores descontínuos."}, {"c": "dou-paragraph", "t": "O PRESIDENTE DO INSTITUTO NACIONAL DE METROLOGIA, QUALIDADE E TECNOLOGIA - INMETRO, no uso das atribuições que lhe conferem a Portaria da Casa Civil nº 1.956, de 07 de março de 2023, e os artigos 4º, § 2º, da Lei nº 5.966, de 11 de dezembro de 1973, e 3º, incisos II e III, da Lei nº 9.933, de 20 de dezembro de 1999, combinado com o disposto nos artigos 18, inciso V, do Anexo I ao Decreto nº 11.221, de 5 de outubro de 2022, e item 4, alínea \"a\" da Resolução nº 8, de 22 de dezembro de 2016, do Conselho Nacional de Metrologia, Normalização e Qualidade Industrial (Conmetro), considerando a Consulta Pública nº xx, de xx de xxxx de xxxx, publicada no Diário Oficial da União de xx de xxxx de xxxx, Seção xxx, páginas xx a xx, e o que consta no Processo SEI nº 0052600.006343/2026-60, resolve:"}, {"c": "dou-paragraph", "t": "Objeto e campo de aplicação"}, {"c": "dou-paragraph", "t": "Art. 1º Fica aprovada a regulamentação técnica metrológica para instrumentos de pesagem automáticos totalizadores descontínuos (balanças de fluxo), composta pelos seguintes anexos:"}, {"c": "dou-paragraph", "t": "I - Anexo A: Regulamento técnico metrológico;"}, {"c": "dou-paragraph", "t": "II - Anexo B: Requisitos técnicos de software para instrumentos de pesagem automáticos totalizadores descontínuos."}, {"c": "dou-paragraph", "t": "Parágrafo único. A regulamentação aplica-se aos instrumentos de pesagem automáticos totalizadores descontínuos (balanças de fluxo) dotados de um receptor de carga na forma de uma tremonha, restrito a instrumentos utilizados em transação comercial."}, {"c": "dou-paragraph", "t": "Disposições permanentes"}, {"c": "dou-paragraph", "t": "Art. 2º Ressalvado o regime de transição previsto nos arts. 5º e 6º, os instrumentos comercializados a partir de 01 de janeiro de 2028 devem corresponder a modelo aprovado pelo Inmetro."}, {"c": "dou-paragraph", "t": "Parágrafo único. Antes da colocação em uso para as finalidades previstas no art. 1º, os instrumentos devem ser aprovados em verificação inicial, observadas as disposições do Anexo A."}, {"c": "dou-paragraph", "t": "Art. 3º O detentor da aprovação de modelo deve assegurar a correspondência do instrumento instalado com o modelo aprovado e disponibilizar as informações necessárias à instalação, à operação e ao controle metrológico legal."}, {"c": "dou-paragraph", "t": "Art. 4º O detentor do instrumento deve manter as condições de instalação e de utilização aprovadas, conservar a identificação e as proteções metrológicas, solicitar as verificações, conforme estabelecido, e disponibilizar o instrumento e meios necessários às atividades de controle metrológico legal."}, {"c": "dou-paragraph", "t": "Disposições transitórias"}, {"c": "dou-paragraph", "t": "Art. 5º Os instrumentos sem aprovação de modelo poderão ser comercializados até 31 de dezembro de 2027, desde que atendam os erros máximos admissíveis previstos para a verificação, conforme requisitos estabelecidos em 3.2 do Anexo A."}, {"c": "dou-paragraph", "t": "Art. 6º Poderão permanecer em uso os instrumentos sem aprovação de modelo que tenham sido adquiridos ou instalados antes da entrada em vigor desta Portaria, bem como aqueles comercializados regularmente no prazo do art. 5º, desde que atendam aos erros máximos admissíveis previstos para a verificação, conforme requisitos estabelecidos em 3.2 do Anexo A."}, {"c": "dou-paragraph", "t": "§ 1º Os instrumentos enquadrados neste artigo podem ser reparados, desde que a intervenção preserve sua identificação e atenda aos erros máximos admissíveis previstos para a verificação após reparo."}, {"c": "dou-paragraph", "t": "§ 2º Os instrumentos enquadrados neste artigo ficam dispensados do exame de correspondência com modelo aprovado."}, {"c": "dou-paragraph", "t": "Infrações"}, {"c": "dou-paragraph", "t": "Art. 7º O descumprimento das obrigações previstas nesta Portaria e dos requisitos obrigatórios da regulamentação aprovada sujeita o infrator às penalidades previstas no art. 8º da Lei nº 9.933, de 20 de dezembro de 1999."}, {"c": "dou-paragraph", "t": "Vigência"}, {"c": "dou-paragraph", "t": "Art. 8º Esta Portaria entra em vigor na data de sua publicação no Diário Oficial da União."}, {"c": "assina", "t": "MARCIO ANDRE OLIVEIRA BRITO"}, {"c": "anexo", "t": "ANEXO AREGULAMENTO TÉCNICO METROLÓGICO PARA INSTRUMENTOS DE PESAGEM AUTOMÁTICOS TOTALIZADORES DESCONTÍNUOS A QUE SE REFERE A PORTARIA INMETRO Nº ...., DE ........ DE ........ DE 2026"}, {"c": "dou-paragraph", "t": "1. OBJETO E CAMPO DE APLICAÇÃO"}, {"c": "dou-paragraph", "t": "1.1. Objeto"}, {"c": "dou-paragraph", "t": "Este Regulamento estabelece os requisitos técnicos e metrológicos e as operações de controle metrológico legal aplicáveis aos instrumentos de pesagem automáticos totalizadores descontínuos (balanças de fluxo), doravante denominados instrumentos."}, {"c": "dou-paragraph", "t": "1.2. Campo de aplicação"}, {"c": "dou-paragraph", "t": "Este Regulamento aplica-se aos instrumentos abrangidos pelo art. 1º da Portaria que o aprova."}, {"c": "dou-paragraph", "t": "O presente Regulamento não se aplica aos seguintes tipos de instrumentos:"}, {"c": "dou-paragraph", "t": "a) instrumentos de \"pesagem em movimento\";"}, {"c": "dou-paragraph", "t": "b) instrumentos que totalizam a carga a granel multiplicando a massa de uma carga constante pré-definida pelo número de ciclos de pesagem."}, {"c": "dou-paragraph", "t": "Neste Regulamento, os instrumentos que, em condições normais de utilização, possam ser operados num modo de pesagem não automático devem também cumprir os requisitos do ponto 3.2.6."}, {"c": "dou-paragraph", "t": "2. TERMOS E DEFINIÇÕES"}, {"c": "dou-paragraph", "t": "Aplicam-se os termos do Vocabulário Internacional de Metrologia - Conceitos fundamentais e gerais e termos associados, adotado pela Portaria Inmetro nº 232, de 8 de maio de 2012, e do Vocabulário Internacional de Termos de Metrologia Legal, adotado pela Portaria Inmetro nº 150, de 29 de março de 2016, além das definições específicas deste Regulamento."}, {"c": "dou-paragraph", "t": "Adicionalmente, para os propósitos deste Regulamento, as seguintes definições se aplicam:"}, {"c": "dou-paragraph", "t": "2.1. Definições gerais"}, {"c": "dou-paragraph", "t": "2.1.1 Instrumento de pesagem"}, {"c": "dou-paragraph", "t": "Instrumento de medição utilizado para determinar a massa de um corpo, utilizando a ação da gravidade sobre esse corpo."}, {"c": "dou-paragraph", "t": "2.1.2. Instrumento de pesagem automático"}, {"c": "dou-paragraph", "t": "Instrumento que pesa sem a intervenção de um operador e que segue um programa predeterminado de processos automáticos característicos do instrumento."}, {"c": "dou-paragraph", "t": "2.1.3. Instrumento de pesagem não automático"}, {"c": "dou-paragraph", "t": "Instrumento que requer a intervenção de um operador durante o processo de pesagem para decidir se o resultado da pesagem é aceitável."}, {"c": "dou-paragraph", "t": "2.1.4. Instrumento de pesagem automático totalizador descontínuo (balança de fluxo)"}, {"c": "dou-paragraph", "t": "Instrumento de pesagem automática que pesa um produto a granel dividindo-o em cargas discretas, determinando a massa de cada carga discreta em sequência, somando os resultados da pesagem e entregando as cargas discretas ao produto a granel."}, {"c": "dou-paragraph", "t": "2.1.5. Instrumento de controle"}, {"c": "dou-paragraph", "t": "Instrumento de pesagem utilizado para determinar o valor verdadeiro convencional da massa das cargas de ensaio durante ensaios de materiais."}, {"c": "dou-paragraph", "t": "Os instrumentos de controle utilizados para ensaios podem ser:"}, {"c": "dou-paragraph", "t": "a) separados do instrumento que está sendo testado; ou"}, {"c": "dou-paragraph", "t": "b) integrados, quando o instrumento em teste dispõe de um modo de pesagem não automático (estático), o que permite que o ciclo de pesagem seja interrompido."}, {"c": "dou-paragraph", "t": "2.1.6. Autoridade metrológica"}, {"c": "dou-paragraph", "t": "Inmetro ou órgão integrante da Rede Brasileira de Metrologia Legal e Qualidade - Inmetro, no âmbito das competências legalmente atribuídas ou delegadas para a atividade de controle metrológico em questão."}, {"c": "dou-paragraph", "t": "2.1.7. Metrologicamente relevante"}, {"c": "dou-paragraph", "t": "Qualquer dispositivo, instrumento, função ou software de um instrumento que influencie o resultado da pesagem ou qualquer outra indicação primária é considerado metrologicamente relevante."}, {"c": "dou-paragraph", "t": "2.1.7. Legalmente relevante"}, {"c": "dou-paragraph", "t": "Parte de um instrumento de medição, dispositivo ou software sujeita ao controle metrológico legal."}, {"c": "dou-paragraph", "t": "2.2. Dispositivo"}, {"c": "dou-paragraph", "t": "Para os fins deste Regulamento, dispositivo é o meio pelo qual uma função específica é executada, independentemente de sua implementação mecânica, eletrônica ou por software."}, {"c": "dou-paragraph", "t": "2.2.1. Dispositivos principais"}, {"c": "dou-paragraph", "t": "2.2.1.1 Receptor de carga"}, {"c": "dou-paragraph", "t": "Parte do instrumento destinada a receber a carga."}, {"c": "dou-paragraph", "t": "2.2.1.2. Dispositivo de transmissão de carga"}, {"c": "dou-paragraph", "t": "Parte do instrumento destinada a transmitir a força produzida pela carga que atua sobre o receptor de carga ao dispositivo de medição de carga."}, {"c": "dou-paragraph", "t": "2.2.1.3. Dispositivo de medição de carga"}, {"c": "dou-paragraph", "t": "Parte do instrumento destinada a medir a massa da carga por meio de um dispositivo de equilíbrio para equilibrar a força proveniente do dispositivo de transmissão de carga e de um dispositivo de indicação ou impressão para exibir o resultado da pesagem em unidades de massa."}, {"c": "dou-paragraph", "t": "2.2.2. Instrumento eletrônico"}, {"c": "dou-paragraph", "t": "Instrumento equipado com um ou mais dispositivos eletrônicos."}, {"c": "dou-paragraph", "t": "2.2.2.1. Dispositivo eletrônico"}, {"c": "dou-paragraph", "t": "Dispositivo que compreende subconjuntos eletrônicos e desempenha uma ou mais funções específicas, geralmente fabricado como uma unidade separada e capaz de ser testado de forma independente."}, {"c": "dou-paragraph", "t": "2.2.2.2. Subconjunto eletrônico"}, {"c": "dou-paragraph", "t": "Parte de um dispositivo eletrônico que emprega componentes eletrônicos e possui uma função própria reconhecível."}, {"c": "dou-paragraph", "t": "2.2.2.3. Componente eletrônico"}, {"c": "dou-paragraph", "t": "A menor entidade física que utiliza a condução de elétrons ou lacunas em semicondutores, gases ou no vácuo."}, {"c": "dou-paragraph", "t": "2.2.2.4. Dispositivo digital"}, {"c": "dou-paragraph", "t": "Dispositivo eletrônico que executa apenas funções digitais e que fornece uma saída ou exibição digitalizada."}, {"c": "dou-paragraph", "t": "2.2.3. Dispositivo de totalização"}, {"c": "dou-paragraph", "t": "Dispositivo que calcula a soma de cargas consecutivas pesadas e descarregadas a granel."}, {"c": "dou-paragraph", "t": "2.2.4. Dispositivo de zero"}, {"c": "dou-paragraph", "t": "Dispositivo para zerar a indicação quando não há carga no receptor de carga."}, {"c": "dou-paragraph", "t": "2.2.4.1. Dispositivo de zero não automático"}, {"c": "dou-paragraph", "t": "Dispositivo para zerar a indicação por um operador."}, {"c": "dou-paragraph", "t": "2.2.4.2. Dispositivo semiautomático de zero"}, {"c": "dou-paragraph", "t": "Dispositivo para zerar a indicação automaticamente após um comando manual."}, {"c": "dou-paragraph", "t": "2.2.4.3. Dispositivo de zero automática"}, {"c": "dou-paragraph", "t": "Dispositivo para zerar a indicação automaticamente, sem a intervenção de um operador."}, {"c": "dou-paragraph", "t": "2.2.4.4. Dispositivo de zeragem inicial"}, {"c": "dou-paragraph", "t": "Dispositivo para zerar a indicação automaticamente no momento em que o instrumento é ligado e antes de estar pronto para uso."}, {"c": "dou-paragraph", "t": "2.2.4.5. Dispositivo de manutenção de zero"}, {"c": "dou-paragraph", "t": "Dispositivo para manter automaticamente a indicação de zero dentro de limites determinados."}, {"c": "dou-paragraph", "t": "2.2.5. Dispositivo de impressão (impressora)"}, {"c": "dou-paragraph", "t": "Dispositivo para produzir uma impressão (2.4.2.3) do resultado da pesagem."}, {"c": "dou-paragraph", "t": "2.2.6. Sistema integrado com câmara de ar"}, {"c": "dou-paragraph", "t": "Instrumento equipado com os recursos adequados de segurança e controle de poeira."}, {"c": "dou-paragraph", "t": "2.2.7. Módulo"}, {"c": "dou-paragraph", "t": "Parte identificável de um instrumento que desempenha uma ou mais funções específicas e que pode ser avaliada separadamente de acordo com os requisitos de desempenho metrológico e técnico do regulamento."}, {"c": "dou-paragraph", "t": "Os módulos de um instrumento de pesagem estão sujeitos a limites de erro parciais especificados."}, {"c": "dou-paragraph", "t": "2.2.7.1. Célula de carga"}, {"c": "dou-paragraph", "t": "Transdutor de força que, após levar em conta os efeitos da aceleração da gravidade e do empuxo do ar no local de sua utilização, mede a massa convertendo a grandeza medida (massa) em outra grandeza medida (saída)."}, {"c": "dou-paragraph", "t": "As células de carga equipadas com componentes eletrônicos que incluem amplificador e conversão analógico-digital (ADC) e processamento de dados (opcionalmente) são denominadas células de carga digitais."}, {"c": "dou-paragraph", "t": "2.2.7.2. Indicador"}, {"c": "dou-paragraph", "t": "Dispositivo eletrônico de um instrumento que pode realizar a conversão analógico-digital do sinal de saída da célula de carga, processa os dados posteriormente e exibe o resultado da pesagem."}, {"c": "dou-paragraph", "t": "2.2.7.3. Módulo de processamento de dados analógicos"}, {"c": "dou-paragraph", "t": "Dispositivo que realiza a conversão analógico-digital do sinal de saída da célula de carga, processa posteriormente os dados e fornece o resultado da pesagem em formato digital por meio de uma interface digital, sem exibi-lo. Pode, opcionalmente, possuir uma ou mais teclas, mouse, tela sensível ao toque ou outros meios para operar o instrumento."}, {"c": "dou-paragraph", "t": "2.2.7.4. Módulo de processamento de dados digitais"}, {"c": "dou-paragraph", "t": "Módulo que processa posteriormente os dados e fornece o resultado da pesagem em formato digital através de uma interface digital, sem o exibir. Pode, opcionalmente, possuir uma ou mais teclas, mouse, tela sensível ao toque ou outros meios para operar o instrumento."}, {"c": "dou-paragraph", "t": "2.2.7.5. Módulo de pesagem"}, {"c": "dou-paragraph", "t": "Parte do instrumento de pesagem que compreende todos os dispositivos mecânicos e eletrônicos (ou seja, receptor de carga, célula de carga e o dispositivo de processamento de dados analógicos), mas que não possui meios para exibir os resultados da pesagem."}, {"c": "dou-paragraph", "t": "Pode, opcionalmente, incluir dispositivos para o processamento adicional de dados (digitais)."}, {"c": "dou-paragraph", "t": "2.2.7.6. Visor remoto"}, {"c": "dou-paragraph", "t": "Terminal sem teclas que pode ser utilizado para as indicações principais ou para a sua repetição."}, {"c": "dou-paragraph", "t": "2.2.7.7. Software"}, {"c": "dou-paragraph", "t": "2.2.7.7.1. Software legalmente relevante"}, {"c": "dou-paragraph", "t": "Software definido no item 1.29 do Anexo B."}, {"c": "dou-paragraph", "t": "2.2.7.7.2. Parâmetro legalmente relevante"}, {"c": "dou-paragraph", "t": "Parâmetro definido no item 1.22 do Anexo B."}, {"c": "dou-paragraph", "t": "Os parâmetros legalmente relevantes podem ser específicos do modelo ou específicos do instrumento individual."}, {"c": "dou-paragraph", "t": "2.2.7.7.3. Parâmetro específico do modelo"}, {"c": "dou-paragraph", "t": "Parâmetro legalmente relevante cujo valor depende exclusivamente do modelo de instrumento."}, {"c": "dou-paragraph", "t": "O valor do parâmetro específico do modelo é fixado na aprovação de modelo."}, {"c": "dou-paragraph", "t": "2.2.7.7.4. Parâmetro específico do dispositivo"}, {"c": "dou-paragraph", "t": "Parâmetro legalmente relevante cujo valor depende do instrumento individual."}, {"c": "dou-paragraph", "t": "Tais parâmetros incluem parâmetros de calibração (por exemplo, ajustes ou correções de intervalo) e parâmetros de configuração (por exemplo, capacidade máxima, capacidade mínima, unidades de medida, etc.)."}, {"c": "dou-paragraph", "t": "Eles são ajustáveis ou selecionáveis apenas em um modo operacional especial do instrumento e podem ser classificados como aqueles que devem ser protegidos (inalteráveis) e aqueles que podem ser acessados (parâmetros configuráveis) por uma pessoa autorizada."}, {"c": "dou-paragraph", "t": "2.2.7.7.5. Identificação do software"}, {"c": "dou-paragraph", "t": "Identificação definida no item 1.14 do Anexo B."}, {"c": "dou-paragraph", "t": "2.2.7.7.6. Separação de software"}, {"c": "dou-paragraph", "t": "Organização do software conforme a definição do item 1.27 do Anexo B."}, {"c": "dou-paragraph", "t": "Quando a separação não atender aos requisitos do Anexo B, todo o software deve ser considerado legalmente relevante."}, {"c": "dou-paragraph", "t": "2.2.8. Dispositivo de armazenamento de dados"}, {"c": "dou-paragraph", "t": "Dispositivo de armazenamento utilizado para manter os dados de pesagem disponíveis após a conclusão da pesagem, para fins legais posteriores."}, {"c": "dou-paragraph", "t": "2.2.9. Interface de comunicação"}, {"c": "dou-paragraph", "t": "Hardware ou software eletrônico, óptico, de rádio ou outro que permite a transmissão automática de informações entre instrumentos e módulos."}, {"c": "dou-paragraph", "t": "2.2.10. Interface do usuário"}, {"c": "dou-paragraph", "t": "Interface que permite a transmissão de informações entre um usuário e o instrumento ou seus componentes de hardware ou software."}, {"c": "dou-paragraph", "t": "2.2.11. Interface de proteção"}, {"c": "dou-paragraph", "t": "Interface (hardware e/ou software) que permite apenas a introdução de dados no dispositivo de processamento de dados de um instrumento, módulo ou componente eletrônico, e que não pode:"}, {"c": "dou-paragraph", "t": "a) exibir dados que não estejam claramente definidos e que possam ser confundidos com um resultado de pesagem;"}, {"c": "dou-paragraph", "t": "b) falsificar resultados de pesagem ou indicações primárias exibidos, processados ou armazenados; ou"}, {"c": "dou-paragraph", "t": "c) ajustar o instrumento ou alterar qualquer fator de ajuste."}, {"c": "dou-paragraph", "t": "2.3. Características metrológicas e d"}, {"c": "dou-paragraph", "t": "2.3.1. Valores de divisão da balança"}, {"c": "dou-paragraph", "t": "Valor expresso em unidades de massa que corresponde à diferença entre:"}, {"c": "dou-paragraph", "t": "a) os valores correspondentes a duas marcas consecutivas da escala para indicação analógica; ou"}, {"c": "dou-paragraph", "t": "b) dois valores indicados consecutivos para indicação digital."}, {"c": "dou-paragraph", "t": "2.3.1.2. Valor de divisão, d"}, {"c": "dou-paragraph", "t": "Valor de divisão de um dispositivo indicador de controle."}, {"c": "dou-paragraph", "t": "2.3.2. Ciclo de pesagem"}, {"c": "dou-paragraph", "t": "Sequência de operações de pesagem que inclui o seguinte:"}, {"c": "dou-paragraph", "t": "a) uma entrega de uma carga ao receptor de carga;"}, {"c": "dou-paragraph", "t": "b) uma única operação de pesagem; e"}, {"c": "dou-paragraph", "t": "c) a descarga em massa de uma única carga discreta."}, {"c": "dou-paragraph", "t": "2.3.3. Faixa de pesagem automática"}, {"c": "dou-paragraph", "t": "Intervalo entre a capacidade mínima e a capacidade máxima."}, {"c": "dou-paragraph", "t": "2.3.3.1. Capacidade máxima, Max"}, {"c": "dou-paragraph", "t": "Maior carga discreta que pode ser pesada automaticamente."}, {"c": "dou-paragraph", "t": "2.3.3.2. Capacidade mínima, Min"}, {"c": "dou-paragraph", "t": "Menor carga discreta que pode ser pesada automaticamente."}, {"c": "dou-paragraph", "t": "2.3.3.3. Carga máxima segura, Lim"}, {"c": "dou-paragraph", "t": "Carga estática máxima que o instrumento pode suportar sem alterar suas qualidades metrológicas."}, {"c": "dou-paragraph", "t": "2.3.4. Valor final do peso"}, {"c": "dou-paragraph", "t": "Valor de peso alcançado estaticamente quando o instrumento está completamente em repouso e equilibrado, sem influências ambientais ou perturbações que afetem a indicação."}, {"c": "dou-paragraph", "t": "2.3.5. Equilíbrio estável"}, {"c": "dou-paragraph", "t": "Condição de equilíbrio em que um instrumento exibe um valor constante ou no máximo dois valores adjacentes, sendo um deles o valor final do peso, para qualquer carga aplicada estaticamente."}, {"c": "dou-paragraph", "t": "Esta definição é aplicável apenas à pesagem estática e não à pesagem dinâmica."}, {"c": "dou-paragraph", "t": "2.3.7. Tempo de aquecimento"}, {"c": "dou-paragraph", "t": "Tempo entre o momento em que a fonte de alimentação é ligada ao instrumento e o momento em que o instrumento está apto a cumprir os requisitos deste Regulamento."}, {"c": "dou-paragraph", "t": "2.3.8. Pesagem estática"}, {"c": "dou-paragraph", "t": "Modo de pesagem estática para fins de teste."}, {"c": "dou-paragraph", "t": "2.3.9. Repetibilidade"}, {"c": "dou-paragraph", "t": "Capacidade de um instrumento de fornecer resultados que concordam entre si nas mesmas condições operacionais de medição."}, {"c": "dou-paragraph", "t": "2.3.10. Durabilidade"}, {"c": "dou-paragraph", "t": "Capacidade de um instrumento de manter suas características de desempenho ao longo de um período de uso."}, {"c": "dou-paragraph", "t": "2.3.11. Dispositivo de verificação automática"}, {"c": "dou-paragraph", "t": "Recurso, operando sem a intervenção de um operador, incorporado em um instrumento e que permite a detecção de falhas significativas e a tomada de medidas correspondentes."}, {"c": "dou-paragraph", "t": "2.4. Indicações e erros"}, {"c": "dou-paragraph", "t": "2.4.1. Indicação"}, {"c": "dou-paragraph", "t": "Valor de quantidade fornecido por um instrumento de medição ou um sistema de medição."}, {"c": "dou-paragraph", "t": "2.4.1.1. Indicação primária"}, {"c": "dou-paragraph", "t": "Indicação, sinal ou símbolo que está sujeito aos requisitos deste Regulamento."}, {"c": "dou-paragraph", "t": "2.4.1.2. Indicações secundárias"}, {"c": "dou-paragraph", "t": "Indicação, sinal ou símbolo que não seja uma indicação primária."}, {"c": "dou-paragraph", "t": "2.4.2. Métodos de indicação"}, {"c": "dou-paragraph", "t": "2.4.2.1. Indicação analógica"}, {"c": "dou-paragraph", "t": "Indicação que permite determinar a posição de equilíbrio com uma precisão de uma fração do intervalo da escala."}, {"c": "dou-paragraph", "t": "2.4.2.2. Indicação digital"}, {"c": "dou-paragraph", "t": "Indicação que apresenta os resultados da pesagem em formato digital."}, {"c": "dou-paragraph", "t": "2.4.2.3 Impressão"}, {"c": "dou-paragraph", "t": "Cópia impressa do resultado da pesagem produzida por uma impressora."}, {"c": "dou-paragraph", "t": "2.4.3. Dispositivo indicador de totalização"}, {"c": "dou-paragraph", "t": "Dispositivo que indica a soma dos valores de peso de cargas consecutivas pesadas e descarregadas a granel."}, {"c": "dou-paragraph", "t": "2.4.3.1. Dispositivo principal de indicação de totalização"}, {"c": "dou-paragraph", "t": "Dispositivo indicador de totalização que indica a soma dos valores de peso de todas as cargas consecutivas pesadas e descarregadas a granel. Este dispositivo não pode ser zerado pelo usuário."}, {"c": "dou-paragraph", "t": "2.4.3.2. Dispositivo indicador de totalização parcial"}, {"c": "dou-paragraph", "t": "Dispositivo indicador de totalização que indica a soma dos valores de peso de um número limitado de cargas consecutivas entregues a granel. Este dispositivo pode ser zerado pelo usuário."}, {"c": "dou-paragraph", "t": "2.4.3.3. Dispositivo de indicação de totalização suplementar"}, {"c": "dou-paragraph", "t": "Dispositivo indicador de totalização com um valor de divisão superior ao do dispositivo indicador de totalização principal e que indica a soma dos valores de peso de cargas consecutivas pesadas durante um longo período de tempo. Este dispositivo pode ser zerado pelo usuário."}, {"c": "dou-paragraph", "t": "2.4.3.4. Dispositivo indicador de controle"}, {"c": "dou-paragraph", "t": "Dispositivo que indica o valor da carga no receptor de carga e permite a utilização do instrumento como instrumento de controle para pesar cargas discretas para fins de controle."}, {"c": "dou-paragraph", "t": "2.4.4. Leitura"}, {"c": "dou-paragraph", "t": "2.4.4.1. Leitura por simples justaposição"}, {"c": "dou-paragraph", "t": "Leitura do resultado da pesagem por simples justaposição de algarismos consecutivos que dão o resultado, sem necessidade de cálculo."}, {"c": "dou-paragraph", "t": "2.4.4.2. Imprecisão global da leitura"}, {"c": "dou-paragraph", "t": "Num instrumento com indicação analógica, esta é igual ao desvio padrão da mesma indicação, cuja leitura é efetuada em condições normais de utilização por vários observadores."}, {"c": "dou-paragraph", "t": "2.4.5. Erros"}, {"c": "dou-paragraph", "t": "2.4.5.1. Erro (de indicação)"}, {"c": "dou-paragraph", "t": "Indicação de um instrumento menos o valor verdadeiro (convencional) da grandeza de entrada correspondente."}, {"c": "dou-paragraph", "t": "2.4.5.2. Erro de arredondamento da indicação digital"}, {"c": "dou-paragraph", "t": "Diferença entre a indicação e o resultado que o instrumento forneceria com indicação analógica."}, {"c": "dou-paragraph", "t": "2.4.5.3. Erro intrínseco"}, {"c": "dou-paragraph", "t": "Erro de um instrumento determinado em condições de referência."}, {"c": "dou-paragraph", "t": "2.4.5.4. Erro intrínseco inicial"}, {"c": "dou-paragraph", "t": "Erro intrínseco de um instrumento determinado antes dos ensaios de desempenho e de estabilidade da faixa."}, {"c": "dou-paragraph", "t": "2.4.5.5. Falha"}, {"c": "dou-paragraph", "t": "Diferença entre o erro de indicação e o erro intrínseco de um instrumento."}, {"c": "dou-paragraph", "t": "Não são consideradas falhas significativas:"}, {"c": "dou-paragraph", "t": "a) erros decorrentes de causas simultâneas e mutuamente independentes no instrumento ou em seus dispositivos de verificação (2.3.11);"}, {"c": "dou-paragraph", "t": "b) falhas que implicam a impossibilidade de realizar qualquer pesagem;"}, {"c": "dou-paragraph", "t": "c) falhas transitórias, variações momentâneas nas indicações que não podem ser interpretadas, memorizadas ou transmitidas como resultado de pesagem; e"}, {"c": "dou-paragraph", "t": "d) falhas tão graves que serão inevitavelmente percebidas por todos os interessados no resultado da pesagem."}, {"c": "dou-paragraph", "t": "2.4.5.7. Estabilidade da escala"}, {"c": "dou-paragraph", "t": "Capacidade de um instrumento de manter a diferença entre a indicação de massa na capacidade máxima e a indicação no zero dentro de limites especificados durante um período de uso."}, {"c": "dou-paragraph", "t": "2.4.5.8. Erro máximo admissível, ema"}, {"c": "dou-paragraph", "t": "Valores extremos de um erro de medição permitidos por este Regulamento para operação e as condições de ensaio consideradas."}, {"c": "dou-paragraph", "t": "2.4.5.9. Registro de auditoria"}, {"c": "dou-paragraph", "t": "Registro histórico (ou arquivo de dados contínuo) dos dados do instrumento, ajustes e operações de pesagem. Podem ser realizadas verificações para garantir que os ajustes e as pesagens foram realizados de acordo com as partes apropriadas deste Regulamento. Cada entrada no registro possui um carimbo de data e hora exclusivo."}, {"c": "dou-paragraph", "t": "2.5. Influências e condições de referência"}, {"c": "dou-paragraph", "t": "2.5.1. Grandeza de influência"}, {"c": "dou-paragraph", "t": "Grandeza que não é o mensurando, mas pode afetar o resultado da medição."}, {"c": "dou-paragraph", "t": "2.5.1.1. Fator de influência"}, {"c": "dou-paragraph", "t": "Grandeza de influência cujo valor se situa dentro das condições nominais de funcionamento especificadas do instrumento."}, {"c": "dou-paragraph", "t": "2.5.1.2. Perturbação"}, {"c": "dou-paragraph", "t": "Grandeza de influência cujo valor se situa dentro dos limites especificados neste Regulamento, mas fora das condições nominais de funcionamento do instrumento."}, {"c": "dou-paragraph", "t": "2.5.2.Condições nominais de funcionamento"}, {"c": "dou-paragraph", "t": "Condições de utilização que determinam os intervalos das grandezas de influência para os quais se pretende que as características metrológicas se situem dentro dos erros máximos admissíveis especificados."}, {"c": "dou-paragraph", "t": "2.5.3. Condições de referência"}, {"c": "dou-paragraph", "t": "Condições de utilização prescritas para testar o desempenho de um instrumento ou para a comparação de resultados de medições."}, {"c": "dou-paragraph", "t": "2.5.4. Condições normais de operação"}, {"c": "dou-paragraph", "t": "Condições de uso prescritas para a operação do instrumento, incluindo tipos de material, instalação no local, manutenção e método de pesagem."}, {"c": "dou-paragraph", "t": "2.6. Ensaios"}, {"c": "dou-paragraph", "t": "2.6.1. Ensaio de material"}, {"c": "dou-paragraph", "t": "Ensaio realizado em um instrumento completo utilizando o tipo de material que se destina a pesar."}, {"c": "dou-paragraph", "t": "2.6.2. Ensaio de simulação"}, {"c": "dou-paragraph", "t": "Ensaio realizado em um instrumento completo ou em parte de um instrumento, no qual qualquer parte da operação de pesagem é simulada."}, {"c": "dou-paragraph", "t": "2.6.3. Ensaio de desempenho"}, {"c": "dou-paragraph", "t": "Ensaio para verificar se o instrumento sob ensaio (ISE) é capaz de desempenhar as funções a que se destina."}, {"c": "dou-paragraph", "t": "2.6.4. Ensaio de estabilidade da escala"}, {"c": "dou-paragraph", "t": "Ensaio para verificar se o ISE é capaz de manter suas características de desempenho ao longo de um período de uso."}, {"c": "dou-paragraph", "t": "3. REQUISITOS METROLÓGICOS"}, {"c": "dou-paragraph", "t": "3.1. Classes de exatidão"}, {"c": "dou-paragraph", "t": "Os instrumentos são divididos em duas classes de exatidão, conforme segue:"}, {"c": "dou-paragraph", "t": "Tabela 1"}, {"c": "", "t": "Classes de Exatidão"}, {"c": "", "t": "Classe"}, {"c": "", "t": "0,2"}, {"c": "", "t": "Classe"}, {"c": "", "t": "0,5"}, {"c": "dou-paragraph", "t": "As classes de exatidão devem ser especificadas de acordo com os erros máximos admissíveis em 3.2 e marcadas no instrumento de acordo com as inscrições obrigatórias em 4.9."}, {"c": "dou-paragraph", "t": "As classes de exatidão devem ser especificadas para a utilização prevista, ou seja, a natureza do produto a ser pesado, o tipo de instalação e outras condições de operação especificadas, em 4 e 5."}, {"c": "dou-paragraph", "t": "3.2. Erros máximos admissíveis"}, {"c": "dou-paragraph", "t": "Tabela 1"}, {"c": "", "t": "Classe de exatidão"}, {"c": "", "t": "Porcentagem da massa da carga totalizada"}, {"c": "", "t": "Verificações / Supervisão metrológica"}, {"c": "", "t": "0,2"}, {"c": "", "t": "±0,10 %"}, {"c": "", "t": "0,5"}, {"c": "", "t": "±0,25 %"}, {"c": "dou-paragraph", "t": "3.2.2. Fatores de influência"}, {"c": "dou-paragraph", "t": "Os erros máximos admissíveis aplicados nos ensaios para avaliar o efeito dos fatores de influência devem ser os especificados na Tabela 2."}, {"c": "dou-paragraph", "t": "3.3. Instrumentos munidos de vários dispositivos"}, {"c": "dou-paragraph", "t": "Para uma determinada carga, a diferença entre as indicações de múltiplos dispositivos indicadores não deve ser superior ao valor absoluto do erro máximo admissível para pesagem automática no caso de dispositivos analógicos, mas deve ser zero entre dispositivos de exibição digital e de impressão."}, {"c": "dou-paragraph", "t": "3.4. Influência de fatores"}, {"c": "dou-paragraph", "t": "3.4.1. Temperatura"}, {"c": "dou-paragraph", "t": "3.4.1.1. Temperaturas estáticas"}, {"c": "dou-paragraph", "t": "Os instrumentos devem cumprir os requisitos metrológicos e técnicos apropriados em limites de temperatura de -10 °C a +40 °C."}, {"c": "dou-paragraph", "t": "Dependendo das condições ambientais locais, no entanto, os limites da faixa de temperatura podem diferir dos acima indicados, desde que sejam especificados nas inscrições obrigatórias. Os limites podem ser combinados utilizando os seguintes limites, desde que as faixas dentro desses limites sejam de pelo menos 30 °C:"}, {"c": "", "t": "Limites de temperatura:"}, {"c": "", "t": "Unidade"}, {"c": "", "t": "temperatura mais baixa"}, {"c": "", "t": "+5"}, {"c": "", "t": "-10"}, {"c": "", "t": "-25"}, {"c": "", "t": "-40"}, {"c": "", "t": "°C"}, {"c": "", "t": "temperatura mais alta"}, {"c": "", "t": "+30"}, {"c": "", "t": "+40"}, {"c": "", "t": "+55"}, {"c": "", "t": "+70"}, {"c": "dou-paragraph", "t": "3.5. Unidades de medição"}, {"c": "dou-paragraph", "t": "As unidades de massa a serem utilizadas em um instrumento são:"}, {"c": "dou-paragraph", "t": "a) grama (g);"}, {"c": "dou-paragraph", "t": "b) quilograma (kg);"}, {"c": "dou-paragraph", "t": "c) tonelada (t)."}, {"c": "dou-paragraph", "t": "4. REQUISITOS TÉCNICOS"}, {"c": "dou-paragraph", "t": "4.1. Adequação para uso"}, {"c": "dou-paragraph", "t": "Um instrumento deve ser projetado de modo a adequar-se ao método de operação e às cargas para as quais se destina. Deve ter uma construção suficientemente robusta para que mantenha suas características metrológicas durante todo seu tempo de uso."}, {"c": "dou-paragraph", "t": "4.2. Segurança do funcionamento"}, {"c": "dou-paragraph", "t": "4.2.1. Utilização fraudulenta"}, {"c": "dou-paragraph", "t": "Os instrumentos não devem apresentar características suscetíveis a facilitar seu uso fraudulento."}, {"c": "dou-paragraph", "t": "4.2.2. Avaria acidental e desajuste"}, {"c": "dou-paragraph", "t": "Um instrumento deve ser construído de forma a que uma avaria acidental ou um mau ajuste dos elementos de comando, suscetíveis de perturbar o seu funcionamento correto, não possam ocorrer sem que o seu efeito seja evidente."}, {"c": "dou-paragraph", "t": "4.2.3. Sobra no receptor de carga"}, {"c": "dou-paragraph", "t": "O projeto do receptor de carga e o funcionamento do instrumento devem ser tais que os resultados da pesagem não sejam prejudicados por qualquer variação na quantidade de carga que permaneça no receptor de carga após a descarga durante um ciclo de pesagem."}, {"c": "dou-paragraph", "t": "4.2.4. Sobrecarga e carga máxima de segurança, Lim"}, {"c": "dou-paragraph", "t": "O projeto e o funcionamento do instrumento devem ser tais que os resultados da pesagem não sejam prejudicados por qualquer carga que:"}, {"c": "dou-paragraph", "t": "a) exceda a carga máxima de segurança (2.3.3.3) sem que seu efeito seja evidente; e/ou"}, {"c": "dou-paragraph", "t": "b) resulte em sobrecarga (2.3.3.4), devido a um fluxo de massa inconstante ou que aumente abruptamente durante um ciclo de pesagem."}, {"c": "dou-paragraph", "t": "4.2.6. Utilização como instrumento de pesagem não automático"}, {"c": "dou-paragraph", "t": "Um instrumento a ser utilizado como instrumento de pesagem não automático deve:"}, {"c": "dou-paragraph", "t": "a) estar equipado com um dispositivo de ativação para operação não automática que impeça a operação automática;"}, {"c": "dou-paragraph", "t": "b) cumprir os requisitos pertinentes da seção 7.2; e"}, {"c": "dou-paragraph", "t": "c) cumprir os requisitos do regulamento técnico metrológico para instrumentos de pesagem não automática em vigor."}, {"c": "dou-paragraph", "t": "4.2.7. Ajustes operacionais"}, {"c": "dou-paragraph", "t": "Não é permitido efetuar ajustes operacionais nem reiniciar os dispositivos indicadores durante uma operação de pesagem automática, com exceção da possibilidade de interromper o ciclo de pesagem no caso do ponto 4.2.5 e durante os ensaios descritos no ponto 7.3."}, {"c": "dou-paragraph", "t": "4.2.8. Exaustor de poeira"}, {"c": "dou-paragraph", "t": "O funcionamento de um exaustor de poeira não deve afetar o resultado da medição."}, {"c": "dou-paragraph", "t": "4.2.10. Equilíbrio estável para pesagem estática"}, {"c": "dou-paragraph", "t": "Condição do instrumento tal que, no caso de impressão, o valor impresso de cada ensaio de pesagem separado não se desvie mais do que 1d t do valor final do peso (ver 2.3.4), ou seja, não apresente mais do que dois valores adjacentes, e, no caso de operações de retorno a zero, seja alcançado um funcionamento correto do dispositivo de acordo com 4.8.1 dentro dos requisitos de precisão relevantes."}, {"c": "dou-paragraph", "t": "Esta condição é válida apenas para cada teste de pesagem individual e não para um grupo de testes."}, {"c": "dou-paragraph", "t": "É considerado em equilíbrio estável a indicação que não desvie mais do que 1d t do valor final do peso, para mais ou para menos (ver 2.3.4)."}, {"c": "dou-paragraph", "t": "4.2.11. Intertravamentos"}, {"c": "dou-paragraph", "t": "Os intertravamentos devem impedir ou indicar o funcionamento do instrumento fora das condições de operação especificadas. São exigidos intertravamentos para:"}, {"c": "dou-paragraph", "t": "a) Tensão mínima de funcionamento (3.4.2);"}, {"c": "dou-paragraph", "t": "b) Carga máxima de segurança (4.2.4);"}, {"c": "dou-paragraph", "t": "c) Ajuste do zero (4.8.3); e"}, {"c": "dou-paragraph", "t": "d) Operação automática (4.2.5)."}, {"c": "dou-paragraph", "t": "4.3. Fixação de componentes, interfaces e controles"}, {"c": "dou-paragraph", "t": "4.3.1. Geral"}, {"c": "dou-paragraph", "t": "Devem ser previstas proteções contra operações suscetíveis de afetar inadvertidamente as suas propriedades metrológicas."}, {"c": "dou-paragraph", "t": "4.3.2. Meios de segurança"}, {"c": "dou-paragraph", "t": "a) O acesso a funções suscetíveis de afetar as propriedades metrológicas deve ser restrito a pessoas autorizadas ou à autoridade metrológica por meios de software e/ou hardware;"}, {"c": "dou-paragraph", "t": "b) Deve ser possível memorizar as intervenções e deve ser possível acessar e exibir essas informações; os registros devem incluir a data e um meio de identificação da pessoa autorizada que realiza a intervenção (ver a) acima); a rastreabilidade das intervenções deve ser assegurada pelo menos durante o período entre verificações periódicas. Os registos não podem ser sobrescritos e, caso a capacidade de armazenamento dos registos se esgote, não será possível realizar mais intervenções sem quebrar um selo físico;"}, {"c": "dou-paragraph", "t": "c) As funções do software devem ser protegidas contra alterações de acordo com os requisitos de 4.6;"}, {"c": "dou-paragraph", "t": "d) A transmissão de dados metrológicos através de interfaces deve ser protegida contra alterações, de acordo com os requisitos do ponto 5.2.6.2;"}, {"c": "dou-paragraph", "t": "e) As possibilidades de proteção disponíveis num instrumento devem ser tais que seja possível proteger separadamente as configurações;"}, {"c": "dou-paragraph", "t": "f) Os dados metrológicos armazenados em dispositivos de armazenamento devem ser protegidos contra alterações em conformidade com 4.5."}, {"c": "dou-paragraph", "t": "4.4. Indicação e registro dos resultados de pesagem"}, {"c": "dou-paragraph", "t": "Os instrumentos devem incluir um dispositivo principal de indicação de totalização e um dispositivo de registro."}, {"c": "dou-paragraph", "t": "Os instrumentos podem incluir um ou mais dispositivos suplementares de indicação de totalização, dispositivos de indicação de totalização parcial e dispositivos de armazenamento de dados."}, {"c": "dou-paragraph", "t": "4.4.1.Qualidade da indicação"}, {"c": "dou-paragraph", "t": "A leitura das indicações primárias (ver 2.4.1.1) deve ser confiável, fácil e inequívoca:"}, {"c": "dou-paragraph", "t": "a) os algarismos que constituem as indicações primárias devem ter dimensão, forma e nitidez que facilitem a leitura;"}, {"c": "dou-paragraph", "t": "b) a numeração e a impressão devem permitir que os algarismos que constituem os resultados sejam lidos por simples justaposição (ver 2.4.4.1)."}, {"c": "dou-paragraph", "t": "4.4.2. Forma da indicação"}, {"c": "dou-paragraph", "t": "4.4.2.1. Unidade de massa"}, {"c": "dou-paragraph", "t": "Os resultados da pesagem devem conter os nomes ou símbolos das unidades de massa em que são expressos. Para cada indicação de massa, deve ser utilizada apenas uma unidade de massa."}, {"c": "dou-paragraph", "t": "4.4.2.2. Indicação digital"}, {"c": "dou-paragraph", "t": "Uma indicação digital de zero deve incluir a exibição de um zero em todas as posições à direita do sinal decimal e em pelo menos uma posição à esquerda. Quando não forem exibidos valores decimais, deve ser exibido um zero em cada posição da divisão exibida."}, {"c": "dou-paragraph", "t": "Uma fração decimal deve ser separada da parte inteira por um separador decimal (vírgula ou ponto, de acordo com as normas nacionais), devendo a indicação mostrar pelo menos um algarismo à esquerda do separador e todos os algarismos à direita."}, {"c": "dou-paragraph", "t": "O sinal de ponto decimal deve estar alinhado com a parte inferior dos algarismos"}, {"c": "dou-paragraph", "t": "4.4.2.3. Valor de divisão"}, {"c": "dou-paragraph", "t": "Exceto no caso de um dispositivo de indicação de totalização suplementar, os valores de divisão de todos os dispositivos de indicação de totalização devem ser os mesmos."}, {"c": "dou-paragraph", "t": "A forma do valor de divisão deve ser conforme especificado em 3.2.3."}, {"c": "dou-paragraph", "t": "Quando o valor de divisão for alterado automaticamente, o sinal decimal deve manter sua posição no visor."}, {"c": "dou-paragraph", "t": "4.4.3. Dispositivos de indicação de totalização"}, {"c": "dou-paragraph", "t": "Aplica-se o seguinte:"}, {"c": "dou-paragraph", "t": "a) Um dispositivo indicador de totalização deve permitir uma leitura confiável, clara e inequívoca dos resultados por simples justaposição e deve ostentar o símbolo da unidade de massa apropriada;"}, {"c": "dou-paragraph", "t": "b) A impressão deve ser nítida e permanente para o uso pretendido. Os números impressos devem ter, no mínimo, 2 mm de altura;"}, {"c": "dou-paragraph", "t": "c) No funcionamento automático, não deve ser possível zerar qualquer dispositivo de totalização;"}, {"c": "dou-paragraph", "t": "d) Não deve ser possível zerar o dispositivo indicador de totalização parcial, a menos que o último total indicado antes do zeramento seja automaticamente registrado quando o funcionamento automático for interrompido;"}, {"c": "dou-paragraph", "t": "e) A indicação do dispositivo indicador de controle (2.4.3.4) deve ter uma resolução superior (não superior a 0,2 d t ) à do dispositivo indicador de totalização principal;"}, {"c": "dou-paragraph", "t": "f) Durante a pesagem estática em operações não automáticas, a impressão deve ser inibida se os critérios de estabilidade em 4.2.10 não forem cumpridos."}, {"c": "dou-paragraph", "t": "4.4.4. Dispositivos indicadores combinados"}, {"c": "dou-paragraph", "t": "Dois ou mais modelos de dispositivos de indicação podem ser combinados de modo que a indicação necessária possa ser exibida sob demanda, desde que seja claramente identificada."}, {"c": "dou-paragraph", "t": "4.4.5. Instrumentos com tara"}, {"c": "dou-paragraph", "t": "No caso de instrumentos utilizados para receber (pesagem), o valor de referência em vazio deve ser determinado e registrado apenas no início de cada ciclo de pesagem."}, {"c": "dou-paragraph", "t": "No caso de instrumentos utilizados para entregar (pesagem de saída), o valor de referência sem carga deve ser determinado e registrado somente após o valor de referência da carga bruta para cada ciclo de pesagem ter sido indicado e registrado."}, {"c": "dou-paragraph", "t": "4.5. Dispositivo de armazenamento de dados"}, {"c": "dou-paragraph", "t": "Os dados metrológicos podem ser armazenados em uma memória do instrumento ou em armazenamento externo para uso posterior. Os dados armazenados devem ser adequadamente protegidos contra alterações durante o processo de transmissão e/ou armazenamento dos dados, e devem conter todas as informações relevantes necessárias para reconstruir uma pesagem anterior."}, {"c": "dou-paragraph", "t": "Segurança do armazenamento de dados:"}, {"c": "dou-paragraph", "t": "a) Os requisitos apropriados de 4.3;"}, {"c": "dou-paragraph", "t": "b) Se o software responsável pelo armazenamento de dados puder ser transmitido para o instrumento ou baixado nele, esses processos devem ser protegidos de acordo com os requisitos do ponto 4.6;"}, {"c": "dou-paragraph", "t": "c) Os atributos de identificação e segurança dos dispositivos de armazenamento externos devem ser verificados automaticamente para garantir a integridade e a autenticidade;"}, {"c": "dou-paragraph", "t": "d) Os suportes de armazenamento intercambiáveis para armazenamento de dados de medição não precisam ser selados, desde que os dados armazenados sejam protegidos por uma soma de verificação específica ou código-chave;"}, {"c": "dou-paragraph", "t": "e) Quando a capacidade de armazenamento estiver esgotada, novos dados poderão substituir os dados mais antigos, desde que não haja prejuízo ao proprietário dos dados antigos."}, {"c": "dou-paragraph", "t": "4.6. Software"}, {"c": "dou-paragraph", "t": "Os componentes de software e de hardware associados às funções legalmente relevantes devem atender ao Anexo B. Os requisitos específicos aplicam-se às funcionalidades e arquiteturas efetivamente presentes no instrumento."}, {"c": "dou-paragraph", "t": "4.7. Instrumentos com dispositivo de indicação de controle"}, {"c": "dou-paragraph", "t": "Para instrumentos com um dispositivo indicador de controle, o receptor de carga deve ter capacidade para suportar uma quantidade de pesos-padrão de acordo com a Tabela 3."}, {"c": "dou-paragraph", "t": "4.8. Dispositivos de zero"}, {"c": "dou-paragraph", "t": "Os instrumentos que não realizam a tara após cada descarga devem ser equipados com um dispositivo de zero."}, {"c": "dou-paragraph", "t": "4.8.1. Precisão do ajuste"}, {"c": "dou-paragraph", "t": "Após o zero, o efeito do desvio de zero no resultado da pesagem não deve ser superior a ± 0,25 d."}, {"c": "dou-paragraph", "t": "4.8.2. Efeito máximo"}, {"c": "dou-paragraph", "t": "O efeito de qualquer dispositivo de zero não pode alterar a capacidade máxima de pesagem do instrumento."}, {"c": "dou-paragraph", "t": "O efeito dos dispositivos de ajuste e acompanhamento do zero não deve exceder 4% da capacidade máxima, e o do dispositivo de ajuste inicial do zero não deve exceder 20% da capacidade máxima."}, {"c": "dou-paragraph", "t": "4.9.4. Marcações complementares"}, {"c": "dou-paragraph", "t": "Dependendo da utilização específica do instrumento, podem ser exigidas marcações suplementares na aprovação. Tais como:"}, {"c": "dou-paragraph", "t": "a) uso exclusivo para ...;"}, {"c": "dou-paragraph", "t": "b) o selo não garante/garante somente ...;"}, {"c": "dou-paragraph", "t": "c) a ser utilizado como a seguir: ..."}, {"c": "dou-paragraph", "t": "d) código de segurança."}, {"c": "dou-paragraph", "t": "Podem ser exigidas marcações adicionais na verificação inicial para especificar os tipos de produtos e as condições de pesagem relacionadas, tais como:"}, {"c": "dou-paragraph", "t": "a) densidade do produto."}, {"c": "dou-paragraph", "t": "5. REQUISITOS TÉCNICOS PARA INSTRUMENTOS ELETRÔNICOS"}, {"c": "dou-paragraph", "t": "5.1. Requisitos gerais de verificação"}, {"c": "dou-paragraph", "t": "Os instrumentos eletrônicos devem cumprir os seguintes requisitos, além dos requisitos aplicáveis de todas as outras cláusulas deste regulamento."}, {"c": "dou-paragraph", "t": "5.1.1. Condições normais de funcionamento"}, {"c": "dou-paragraph", "t": "Os instrumentos de pesagem eletrônicos devem ser projetados e fabricados de forma a não excederem os erros máximos admissíveis nas condições normais de funcionamento."}, {"c": "dou-paragraph", "t": "5.1.2. Perturbações"}, {"c": "dou-paragraph", "t": "Os instrumentos eletrônicos devem ser projetados e fabricados de forma que, quando expostos a perturbações:"}, {"c": "dou-paragraph", "t": "a) não ocorram falhas significativas, ou"}, {"c": "dou-paragraph", "t": "b) as falhas significativas sejam detectadas e corrigidas."}, {"c": "dou-paragraph", "t": "É permitida uma falha igual ou inferior ao valor especificado em 2.4.5.6 (1 d t ), independentemente do valor do erro de indicação."}, {"c": "dou-paragraph", "t": "5.1.3. Durabilidade"}, {"c": "dou-paragraph", "t": "Os instrumentos eletrônicos devem ser projetados e fabricados de modo que sua capacidade de atender aos requisitos dos itens 5.1.1 e 5.1.2 seja mantida durante um período de uso de acordo com a finalidade do instrumento."}, {"c": "dou-paragraph", "t": "5.1.4. Avaliação de modelo"}, {"c": "dou-paragraph", "t": "Considera-se que um determinado modelo ou família de modelos de instrumento eletrônico cumpre os requisitos dos itens 5.1.1, 5.1.2 e 5.1.3 se for aprovado nos exames e ensaios especificados neste regulamento, conforme procedimentos de exame e ensaios definidos em norma Inmetro, sem prejuízo dos requisitos de software do Anexo B."}, {"c": "dou-paragraph", "t": "5.1.5. Aplicação dos requisitos relativos a perturbações"}, {"c": "dou-paragraph", "t": "Os requisitos do ponto 5.1.2 podem ser aplicados separadamente a:"}, {"c": "dou-paragraph", "t": "a) cada causa individual de falha significativa e/ou"}, {"c": "dou-paragraph", "t": "b) cada parte do instrumento eletrônico."}, {"c": "dou-paragraph", "t": "A escolha entre a aplicação do ponto 5.1.2 a) ou b) fica a critério do fabricante."}, {"c": "dou-paragraph", "t": "5.2. Requisitos funcionais"}, {"c": "dou-paragraph", "t": "5.2.1. Reação a uma falha significativa"}, {"c": "dou-paragraph", "t": "Quando for detectada uma falha significativa, deve ser fornecida uma indicação visual ou sonora, que deve permanecer ativa até que o usuário tome uma ação ou a falha desapareça."}, {"c": "dou-paragraph", "t": "Devem ser previstos meios para preservar todas as informações relativas à carga totalizadas contidas no instrumento quando ocorrer uma falha significativa."}, {"c": "dou-paragraph", "t": "5.2.2. Teste do visor do indicador"}, {"c": "dou-paragraph", "t": "Ao ligar o aparelho (ativação da indicação), deve ser executado um procedimento especial que mostre todos os sinais relevantes do indicador em seus estados ativo e inativo por tempo suficiente para que sejam verificados pelo operador. Isso não se aplica a visores não segmentados, nos quais as falhas se tornam evidentes"}, {"c": "dou-paragraph", "t": "5.2.3. Grandezas de influência"}, {"c": "dou-paragraph", "t": "Um instrumento eletrônico deve cumprir os requisitos de 3.4 e também deve cumprir os requisitos metrológicos e técnicos apropriados a uma umidade relativa de 85 % no limite superior da faixa de temperatura."}, {"c": "dou-paragraph", "t": "5.2.4. Perturbações"}, {"c": "dou-paragraph", "t": "Quando um instrumento eletrônico for submetido às perturbações especificadas em norma Inmetro, deve aplicar-se uma das seguintes condições:"}, {"c": "dou-paragraph", "t": "a) a falha, ou seja, a diferença entre o erro de indicação quando a perturbação está presente e o erro intrínseco, não deve exceder o valor especificado em 2.4.5.6 (1 d t );"}, {"c": "dou-paragraph", "t": "b) o instrumento deve detectar e reagir a uma falha significativa."}, {"c": "dou-paragraph", "t": "5.2.5. Tempo de aquecimento"}, {"c": "dou-paragraph", "t": "Durante o tempo de aquecimento de um instrumento eletrônico, não deve haver indicação ou transmissão do resultado da pesagem e o funcionamento automático deve ser inibido."}, {"c": "dou-paragraph", "t": "5.2.6. Interfaces"}, {"c": "dou-paragraph", "t": "Um instrumento pode estar equipado com interfaces (2.2.9) que permitam a conexão do instrumento a equipamentos externos e com interfaces de usuário (2.2.10) que possibilitem a troca de informações entre um usuário humano e o instrumento. Quando uma interface for utilizada, o instrumento deve continuar a funcionar corretamente e suas funções metrológicas (incluindo todos os parâmetros e softwares metrologicamente relevantes) não devem ser afetadas."}, {"c": "dou-paragraph", "t": "5.2.6.1. Interfaces: informações a serem apresentadas com um instrumento:"}, {"c": "dou-paragraph", "t": "a) Lista de todos os comandos;"}, {"c": "dou-paragraph", "t": "b) Descrição da interface de software;"}, {"c": "dou-paragraph", "t": "c) Breve descrição do seu significado e do seu efeito nas funções e nos dados do instrumento;"}, {"c": "dou-paragraph", "t": "d) Outras descrições da interface."}, {"c": "dou-paragraph", "t": "5.2.6.2. Segurança da interface"}, {"c": "dou-paragraph", "t": "As interfaces não podem permitir que o software e as funções do instrumento relevantes do ponto de vista legal, bem como os dados metrológicos, sejam indevidamente influenciados por outros instrumentos interligados ou por perturbações que atuem sobre a interface."}, {"c": "dou-paragraph", "t": "Uma interface através da qual as funções acima mencionadas não possam ser executadas ou iniciadas não precisa ser protegida. Outras interfaces devem ser protegidas da seguinte forma:"}, {"c": "dou-paragraph", "t": "a) Os dados são protegidos com uma interface de proteção (2.2.11), contra interferências;"}, {"c": "dou-paragraph", "t": "b) As funções de hardware e software devem cumprir os requisitos apropriados de proteção previstos nos pontos 4.3 e 4.6;"}, {"c": "dou-paragraph", "t": "c) Deve ser facilmente possível verificar a autenticidade e a integridade dos dados transmitidos para o instrumento;"}, {"c": "dou-paragraph", "t": "d) Outros instrumentos que devam ser conectados às interfaces devem ser protegidos de forma a inibir automaticamente o funcionamento do instrumento em caso de ausência ou funcionamento inadequado do dispositivo exigido."}, {"c": "dou-paragraph", "t": "5.2.7. Falha na tensão da rede elétrica CA"}, {"c": "dou-paragraph", "t": "Um instrumento que funcione a partir da rede elétrica CA deve, em caso de falha no fornecimento de tensão, reter suas informações metrológicas no momento da falha por pelo menos 24 horas. A comutação para uma tensão de alimentação de emergência não pode causar uma falha significativa."}, {"c": "dou-paragraph", "t": "5.2.8. Tensão de alimentação da rede de corrente contínua ou por bateria"}, {"c": "dou-paragraph", "t": "Os instrumentos alimentados por bateria e pela rede de corrente contínua devem, sempre que a tensão cair abaixo do nível mínimo de operação (ver 3.4.2), continuar a funcionar corretamente, exibir uma mensagem de erro ou ser automaticamente colocados fora de serviço."}, {"c": "dou-paragraph", "t": "6. CONTROLE METROLÓGICO LEGAL"}, {"c": "dou-paragraph", "t": "O controle metrológico legal dos instrumentos deve, em conformidade com a legislação nacional, consistir no seguinte:"}, {"c": "dou-paragraph", "t": "a) aprovação de modelo;"}, {"c": "dou-paragraph", "t": "b) verificação inicial ou declaração de conformidade;"}, {"c": "dou-paragraph", "t": "c) verificação subsequente;"}, {"c": "dou-paragraph", "t": "d) supervisão metrológica."}, {"c": "dou-paragraph", "t": "6.1. Aprovação de modelo"}, {"c": "dou-paragraph", "t": "6.1.1. Documentação"}, {"c": "dou-paragraph", "t": "A solicitação de aprovação de modelo deve incluir a apresentação à autoridade metrológica das seguintes informações e documentos:"}, {"c": "dou-paragraph", "t": "a) características metrológicas do instrumento (item 3);"}, {"c": "dou-paragraph", "t": "b) conjunto padrão de especificações para o instrumento;"}, {"c": "dou-paragraph", "t": "c) descrição funcional dos componentes e dispositivos;"}, {"c": "dou-paragraph", "t": "d) desenhos, diagramas e fotografias do instrumento que expliquem a sua construção e funcionamento;"}, {"c": "dou-paragraph", "t": "e) descrição e aplicação de componentes de fixação, intertravamentos, dispositivos de ajuste, controles, etc. (4.2, 4.3, 4.6, 4.9);"}, {"c": "dou-paragraph", "t": "f) dispositivos de registro e indicação (4.4);"}, {"c": "dou-paragraph", "t": "g) dispositivo de armazenamento de dados (4.5);"}, {"c": "dou-paragraph", "t": "h) dispositivos de retorno a zero (4.8);"}, {"c": "dou-paragraph", "t": "i) interfaces (tipos, uso previsto, instruções de imunidade a influências externas) (5.2.6);"}, {"c": "dou-paragraph", "t": "j) para instrumentos controlados por software: informações detalhadas sobre o software (4.6);"}, {"c": "dou-paragraph", "t": "k) descrição da função de equilíbrio estável do instrumento (4.2.10);"}, {"c": "dou-paragraph", "t": "l) desenho ou fotografia do instrumento mostrando o princípio e a localização das marcas de selagem, e inscrições (4.9);"}, {"c": "dou-paragraph", "t": "m) instruções de operação, manual de operação;"}, {"c": "dou-paragraph", "t": "n) documento que demonstre que a concepção e a construção do instrumento cumprem os requisitos deste Regulamento."}, {"c": "dou-paragraph", "t": "6.1.2. Requisitos gerais"}, {"c": "dou-paragraph", "t": "A avaliação de modelo deve ser realizada em um ou mais exemplares que representem o modelo, ou família de modelos, definitivo apresentado, de forma adequada para a realização de ensaios. Os instrumentos podem ser ensaiados em local adequado, mutuamente acordado, que permita a completa avaliação do instrumento. Os fatores de influência devem ser aplicados durante os ensaios de simulação em dispositivos indicadores, se aplicável, de forma a revelar uma alteração no resultado da medição para qualquer processo de pesagem ao qual o instrumento possa ser aplicado. A avaliação deve consistir nos ensaios especificados em 6.1.2.2."}, {"c": "dou-paragraph", "t": "6.1.2.1. Avaliação de modelo"}, {"c": "dou-paragraph", "t": "Os documentos apresentados devem ser examinados e os ensaios realizados para verificar se os instrumentos atendem:"}, {"c": "dou-paragraph", "t": "a) os requisitos metrológicos do item 3, particularmente no que se refere aos erros máximos admissíveis, quando o instrumento for operado de acordo com as especificações do fabricante;"}, {"c": "dou-paragraph", "t": "b) os requisitos técnicos do item 4; e"}, {"c": "dou-paragraph", "t": "c) os requisitos do item 5 para instrumentos eletrônicos."}, {"c": "dou-paragraph", "t": "Os ensaios devem ser realizados de forma a evitar o dispêndio desnecessário de recursos e, quando se tratar do mesmo instrumento, o resultado desses ensaios pode ser considerado para a verificação inicial."}, {"c": "dou-paragraph", "t": "Devem ser examinadas as características metrológicas do instrumento, em conformidade com 4.9, e as especificações relativas à abordagem modular dos módulos do instrumento, em conformidade com 6.1.4."}, {"c": "dou-paragraph", "t": "O requerente deve fornecer equipamentos, pessoal e um instrumento de controle para a realização dos ensaios."}, {"c": "dou-paragraph", "t": "6.1.2.2. Ensaios de materiais"}, {"c": "dou-paragraph", "t": "Os ensaios de materiais a serem realizados no local de instalação devem ser realizados de acordo com o procedimento de ensaio descrito em norma Inmetro."}, {"c": "dou-paragraph", "t": "O instrumento de controle utilizado para a realização dos ensaios de materiais deve estar em conformidade com 7.2."}, {"c": "dou-paragraph", "t": "6.1.2.3. Ensaios de simulação"}, {"c": "dou-paragraph", "t": "As grandezas de influência devem ser aplicadas durante os ensaios de simulação de forma a revelar uma alteração no resultado da pesagem para qualquer processo de pesagem ao qual o instrumento possa ser aplicado, de acordo com 3.4, para todos os instrumentos; e com 5, para instrumentos eletrônicos."}, {"c": "dou-paragraph", "t": "6.1.3. Portaria de aprovação de modelo e determinação das classes"}, {"c": "dou-paragraph", "t": "A portaria de aprovação de modelo deve indicar as classes de exatidão apropriadas 0,2 e 0,5, conforme especificado na fase de avaliação de modelo, e deve ser determinado pela conformidade com os requisitos metrológicos na verificação inicial do instrumento."}, {"c": "dou-paragraph", "t": "6.1.4. Módulos"}, {"c": "dou-paragraph", "t": "Mediante acordo com a autoridade metrológica, o fabricante pode definir e apresentar módulos a serem examinados separadamente. Isso é particularmente relevante nos seguintes casos:"}, {"c": "dou-paragraph", "t": "a) quando for difícil ou impossível testar o instrumento como um todo;"}, {"c": "dou-paragraph", "t": "b) quando os módulos são fabricados e/ou colocados no mercado como unidades separadas a serem incorporadas num instrumento completo;"}, {"c": "dou-paragraph", "t": "c) quando o requerente deseja incluir uma variedade de módulos no modelo aprovado;"}, {"c": "dou-paragraph", "t": "d) quando um módulo se destina a ser utilizado em vários modelos de instrumentos de pesagem (em particular células de carga, indicadores, armazenamento de dados)."}, {"c": "dou-paragraph", "t": "6.2. Verificação inicial"}, {"c": "dou-paragraph", "t": "6.2.1. Requisitos gerais"}, {"c": "dou-paragraph", "t": "A verificação inicial deve ser realizada de acordo com os regulamentos Inmetro vigentes para estabelecer a conformidade do instrumento com o modelo aprovado e/ou com os requisitos deste RTM."}, {"c": "dou-paragraph", "t": "Os instrumentos devem ser ensaiados para verificar se cumprem os requisitos do item 3 (exceto 3.4) e do item 4para qualquer produto a que se destinem e quando operados em condições normais de pesagem."}, {"c": "dou-paragraph", "t": "Os ensaios devem ser realizados no local da instalação, com o instrumento totalmente montado e fixado na posição em que se destina a ser utilizado. A instalação de um instrumento deve ser concebida de modo a que a operação de pesagem seja a mesma, quer se trate de ensaios, quer de operações normais de pesagem."}, {"c": "dou-paragraph", "t": "6.2.2. Ensaios operacionais"}, {"c": "dou-paragraph", "t": "Os instrumentos devem ser ensaiados no seu modo normal de funcionamento automático e de acordo com os procedimentos de ensaio descritos em norma Inmetro."}, {"c": "dou-paragraph", "t": "Os ensaios devem ser realizados de forma a evitar o dispêndio desnecessário de recursos. Em situações apropriadas e para evitar a duplicação de ensaios previamente realizados no instrumento para avaliação de modelo conforme 6.1.2.2, o Inmetro pode utilizar os resultados dos ensaios observados para a verificação inicial."}, {"c": "dou-paragraph", "t": "O requerente deve fornecer o material, o equipamento, o pessoal qualificado para a realização dos ensaios."}, {"c": "dou-paragraph", "t": "Os instrumentos utilizados na pesagem estática devem estar de acordo com a norma Inmetro sobre procedimentos de ensaio e devem cumprir os requisitos de 4.2.6."}, {"c": "dou-paragraph", "t": "6.2.3. Conformidade"}, {"c": "dou-paragraph", "t": "A conformidade com o modelo aprovado e/ou com o presente RTM, deve abranger:"}, {"c": "dou-paragraph", "t": "a) o atendimento aos erros máximos admissíveis aplicáveis, conforme especificado em 3.2.1;"}, {"c": "dou-paragraph", "t": "b) o funcionamento correto de todos os dispositivos, por exemplo, intertravamentos, dispositivos de indicação e registro;"}, {"c": "dou-paragraph", "t": "c) os materiais de construção e o projeto, na medida em que sejam relevantes do ponto de vista metrológico;"}, {"c": "dou-paragraph", "t": "d) se for o caso, uma lista dos ensaios realizados."}, {"c": "dou-paragraph", "t": "6.2.4. Inspeção visual"}, {"c": "dou-paragraph", "t": "Antes do ensaio, o instrumento deve ser inspecionado visualmente quanto a:"}, {"c": "dou-paragraph", "t": "a) características metrológicas;"}, {"c": "dou-paragraph", "t": "b) inscrições e posições para marcas de verificação e selagem."}, {"c": "dou-paragraph", "t": "6.2.5. Marcação e fixação"}, {"c": "dou-paragraph", "t": "De acordo com a legislação nacional, a verificação inicial deve ser atestada por meio de certificado de verificação, que deve estar disponível para uma eventual supervisão metrológica. A legislação nacional também deve exigir a proteção de dispositivos cuja desmontagem ou desajuste possa alterar as características metrológicas do instrumento sem que as alterações sejam claramente visíveis. As disposições em 4.3 e 4.9 devem ser observadas."}, {"c": "dou-paragraph", "t": "6.3. Verificação subsequente"}, {"c": "dou-paragraph", "t": "6.3.1 A verificação subsequente deve ser realizada de acordo com as mesmas disposições em 6.2.2, sendo os limites de erro da verificação inicial. A marcação e a fixação devem ser feitas de acordo com 6.2.5."}, {"c": "dou-paragraph", "t": "6.3.2. A verificação periódica deve ser realizada em intervalo não superior a 2 anos, contado da última verificação. A aprovação de modelo pode estabelecer limite adicional de número de pesagens, tecnicamente fundamentado; nesse caso, prevalece o evento que ocorrer primeiro, e o contador correspondente deve ser protegido e verificável."}, {"c": "dou-paragraph", "t": "6.3.3. O instrumento deve ser submetido à verificação após reparo antes do retorno ao uso quando sofrer ajuste, reparo ou intervenção capaz de alterar suas características metrológicas relevantes, com ou sem rompimento de lacres. As intervenções devem ser registradas e as proteções restabelecidas."}, {"c": "dou-paragraph", "t": "6.3.4. Relatórios de calibração, ajuste e manutenção podem ser utilizados como evidências complementares na verificação subsequente, mas não substituem os ensaios e a decisão de aprovação exigidos por este Regulamento."}, {"c": "dou-paragraph", "t": "6.3.5. As evidências complementares podem ser apresentadas nas seguintes formas, desde que sejam asseguradas sua autenticidade, integridade e vinculação ao instrumento:"}, {"c": "dou-paragraph", "t": "a) documentos físicos;"}, {"c": "dou-paragraph", "t": "b) documentos obtidos por acesso remoto; ou"}, {"c": "dou-paragraph", "t": "c) arquivos eletrônicos fornecidos em meio adequado."}, {"c": "dou-paragraph", "t": "6.3.6. O detentor deve disponibilizar os meios necessários à consulta e à avaliação dessas evidências. O resultado da verificação deve ser registrado pelo órgão competente, com a indicação dos exames e ensaios executados."}, {"c": "dou-paragraph", "t": "Em todos os casos acima o fornecimento dos meios para a avaliação é de responsabilidade do detentor do instrumento."}, {"c": "dou-paragraph", "t": "6.4. Supervisão Metrológica"}, {"c": "dou-paragraph", "t": "A supervisão metrológica deve observar as disposições aplicáveis do item 6.2, com os mesmos erros máximos admissíveis das verificações. A marcação e a fixação podem permanecer inalteradas ou ser renovadas conforme o item 6.2.5."}, {"c": "dou-paragraph", "t": "7. MÉTODOS DE ENSAIO"}, {"c": "dou-paragraph", "t": "7.2. Instrumentos de controle e padrões de ensaio"}, {"c": "dou-paragraph", "t": "Um instrumento de controle e pesos padrão que atendam aos requisitos apropriados do item 6 devem estar disponíveis para determinar o valor verdadeiro convencional da massa de cada carga de ensaio. O instrumento de controle deve cumprir a legislação metrológica e normas Inmetro vigentes."}, {"c": "dou-paragraph", "t": "7.2.1. Utilização de um instrumento de controle adequadamente concebido"}, {"c": "dou-paragraph", "t": "Quando um receptor de carga não puder ser carregado com pesos-padrão suficientes para verificar e determinar o erro de arredondamento do dispositivo indicador do instrumento de controle ou do dispositivo indicador de totalização parcial, o instrumento deve ser submetido a ensaios de material pelo procedimento de ensaio separado, conforme norma Inmetro. Para este método, deve estar disponível um instrumento de controle que deve cumprir a legislação metrológica e normas Inmetro vigentes, de modo que os ensaios de material possam ser conduzidos de forma eficaz e eficiente."}, {"c": "dou-paragraph", "t": "7.2.2. Pesos-padrão"}, {"c": "dou-paragraph", "t": "Os pesos ou massas padrão de referência utilizados para os ensaios de avaliação de modelo ou verificação de um instrumento devem atender aos requisitos metrológicos da portaria Inmetro n° 289, de 5 de julho de 2021 ou OIML R 111: 2004, no caso de pesos ou massas padrão com valor nominal maior que 50 kg. O erro dos pesos adicionais utilizados para determinar o erro de arredondamento do instrumento de controle não pode exceder um quinto do erro máximo admissível do instrumento a ser verificado para a carga, conforme especificado em 3.2.2 para a verificação inicial."}, {"c": "dou-paragraph", "t": "7.2.3. Substituição de pesos-padrão"}, {"c": "dou-paragraph", "t": "Ao ensaiar instrumentos no local de utilização (aplicação), em vez de pesos-padrão, pode ser utilizada qualquer outra carga constante, desde que sejam utilizados pesos-padrão correspondentes a, pelo menos, 50 % do valor máximo. Em vez de 50 % do valor máximo, a proporção de pesos-padrão pode ser reduzida para:"}, {"c": "dou-paragraph", "t": "a) 35 % de Max se o erro de repetibilidade for < 0,3 d;"}, {"c": "dou-paragraph", "t": "b) 20 % de Max se o erro de repetibilidade for < 0,2 d."}, {"c": "dou-paragraph", "t": "O erro de repetibilidade deve ser determinado com uma carga (pesos ou qualquer outra carga) de valor próximo ao valor em que a substituição é feita, colocando-a três vezes no receptor de carga."}, {"c": "dou-paragraph", "t": "7.3. Interrupção da operação automática O instrumento de controle integral utiliza um programa de parada de ensaio como parte do programa de pesagem automática para interromper automaticamente a operação de pesagem automática duas vezes, conforme especificado na norma Inmetro pertinente, durante cada ciclo de pesagem, a fim de pesar e descarregar uma subdivisão da carga de ensaio."}, {"c": "dou-paragraph", "t": "Se o instrumento de controle integral estiver instalado como um sistema hermético (2.2.6), a interrupção da operação automática durante ciclos de pesagem consecutivos não é possível, e os ensaios devem ser realizados conforme especificado na norma Inmetro pertinente."}, {"c": "dou-paragraph", "t": "7.4. Valor verdadeiro convencional da massa da carga de ensaio"}, {"c": "dou-paragraph", "t": "a) Com o método de verificação separado, a carga de teste deve ser pesada em um instrumento de controle e o resultado deve ser considerado como o valor verdadeiro convencional da massa da carga de teste."}, {"c": "dou-paragraph", "t": "b) Com o método de verificação integral, para cada descarga, o valor da tara subtraído do valor bruto é o valor líquido do material descarregado. A soma dos valores líquidos de todas as descargas na carga de teste deve ser o valor verdadeiro convencional da massa da carga de teste."}, {"c": "dou-paragraph", "t": "Ao utilizar o método de verificação de controle integral, a subdivisão da carga de ensaio é inevitável, e isso também pode ocorrer ao utilizar o método de verificação de controle separado. Ao calcular o valor verdadeiro convencional da massa da carga de ensaio, é necessário considerar a incerteza aumentada devido à subdivisão da carga de ensaio."}, {"c": "dou-paragraph", "t": "7.6. Erro para pesagem automática"}, {"c": "dou-paragraph", "t": "O erro para pesagem automática deve ser a diferença entre o valor verdadeiro convencional da massa da carga de ensaio, conforme especificado em 7.4 para o método de verificação separado ou integral, conforme apropriado, e o valor de peso indicado, observado e registrado conforme especificado em 7.5 para o método de verificação separado ou integral, conforme apropriado."}, {"c": "dou-paragraph", "t": "O erro máximo admissível para pesagem automática deve ser o especificado na Tabela 2 (3.2.1) para a verificação e, conforme apropriado, para a classe do instrumento."}, {"c": "dou-paragraph", "t": "7.7. Exame e ensaios"}, {"c": "dou-paragraph", "t": "O exame e os ensaios de um instrumento de pesagem eletrônico têm por objetivo verificar a conformidade com os requisitos aplicáveis deste Regulamento e, especialmente, com os requisitos do item 5."}, {"c": "dou-paragraph", "t": "7.7.1. Exame"}, {"c": "dou-paragraph", "t": "Um instrumento de pesagem eletrônico deve ser examinado para obter uma avaliação geral de seu projeto e fabricação."}, {"c": "dou-paragraph", "t": "7.7.2. Ensaios de desempenho"}, {"c": "dou-paragraph", "t": "Um instrumento de pesagem eletrônico ou dispositivo eletrônico, conforme o caso, deve ser submetido a ensaios conforme procedimentos especificados na norma Inmetro pertinente, a fim de determinar o seu funcionamento correto."}, {"c": "dou-paragraph", "t": "Os ensaios devem ser realizados no instrumento na sua totalidade, exceto quando o tamanho e/ou a configuração do instrumento não permitirem o ensaio como uma unidade. Nesses casos, os dispositivos eletrônicos separados devem ser submetidos a ensaio. Não se pretende que os dispositivos eletrônicos sejam desmontados para ensaios separados de componentes. Além disso, deve ser realizada uma checagem no instrumento de pesagem em pleno funcionamento ou, se necessário, nos dispositivos eletrônicos em uma configuração simulada que represente suficientemente o instrumento de pesagem. O equipamento deve continuar a funcionar corretamente, conforme especificado na norma Inmetro pertinente."}, {"c": "dou-paragraph", "t": "7.7.3. Ensaios de estabilidade da escala"}, {"c": "dou-paragraph", "t": "Para os ensaios de estabilidade da escala, o instrumento deve ser testado em modo não automático (estático). Deve ser utilizada uma única carga de ensaio estática próxima da capacidade máxima."}, {"c": "dou-paragraph", "t": "O instrumento deve ser submetido a ensaios de estabilidade de escala antes, durante e após ser submetido a ensaios de desempenho."}, {"c": "dou-paragraph", "t": "Quando o instrumento for submetido ao ensaio de estabilidade de escala:"}, {"c": "dou-paragraph", "t": "a) a variação máxima admissível nos erros de indicação não deve exceder metade do valor absoluto do erro máximo admissível no item 3.2.2, Tabela 3 para a carga de teste aplicada em qualquer uma das n medições;"}, {"c": "dou-paragraph", "t": "b) quando as diferenças dos resultados indicarem uma tendência superior a metade da variação admissível especificada acima, o teste deve ser continuado até que a tendência se estabilize ou se inverta, ou até que o erro exceda a variação máxima admissível."}, {"c": "anexo", "t": "ANEXO B REQUISITOS TÉCNICOS DE SOFTWARE PARA INSTRUMENTOS DE PESAGEM AUTOMÁTICOS TOTALIZADORES DESCONTÍNUOS A QUE SE REFERE A PORTARIA INMETRO Nº ...., DE ........ DE ........ DE 2026"}, {"c": "dou-paragraph", "t": "1. Termos e definições"}, {"c": "dou-paragraph", "t": "Para fins deste Regulamento, aplicam-se os seguintes termos e definições."}, {"c": "dou-paragraph", "t": "1.1 Ambiente de execução"}, {"c": "dou-paragraph", "t": "Conjunto de componentes, recursos e condições de hardware e software necessários à execução do software no instrumento."}, {"c": "dou-paragraph", "t": "1.2 Armazenamento de dados legalmente relevantes"}, {"c": "dou-paragraph", "t": "Conservação de dados legalmente relevantes para posterior recuperação ou utilização para finalidade sujeita ao controle metrológico legal."}, {"c": "dou-paragraph", "t": "1.3 Atualização de software"}, {"c": "dou-paragraph", "t": "Processo pelo qual software instalado no instrumento é substituído ou modificado por outra versão ou configuração."}, {"c": "dou-paragraph", "t": "1.4 Autenticidade"}, {"c": "dou-paragraph", "t": "Propriedade pela qual pode ser verificada a origem ou identidade declarada de software, dados, mensagens ou outra informação."}, {"c": "dou-paragraph", "t": "1.5 Autorização"}, {"c": "dou-paragraph", "t": "Concessão a uma pessoa, entidade ou processo do direito de executar determinada função ou operação."}, {"c": "dou-paragraph", "t": "1.6 Cadeia metrológica legalmente relevante"}, {"c": "dou-paragraph", "t": "Conjunto de componentes, funções, dados, parâmetros e interfaces envolvidos no processamento legalmente relevante, desde a aquisição dos sinais de medição até a formação do resultado legalmente relevante."}, {"c": "dou-paragraph", "t": "1.7 Ciclo de pesagem"}, {"c": "dou-paragraph", "t": "Sequência completa de operações executadas automaticamente pelo instrumento, compreendendo o enchimento do receptor de carga, a determinação da massa da carga, a incorporação do valor determinado ao valor acumulado da massa e a descarga do receptor de carga."}, {"c": "dou-paragraph", "t": "1.8 Configuração de software legalmente relevante"}, {"c": "dou-paragraph", "t": "Conjunto identificável de componentes e respectivas versões do software legalmente relevante que determina a configuração de software instalada no instrumento para utilização legalmente relevante."}, {"c": "dou-paragraph", "t": "1.9 Controle de acesso"}, {"c": "dou-paragraph", "t": "Conjunto de mecanismos destinados a restringir o acesso a funções, software, parâmetros, configurações, dados ou outros elementos legalmente relevantes às pessoas, entidades ou processos autorizados."}, {"c": "dou-paragraph", "t": "1.10 Dados legalmente relevantes"}, {"c": "dou-paragraph", "t": "Dados sujeitos ao controle metrológico legal ou utilizados por funções legalmente relevantes, cuja alteração, substituição, perda ou associação incorreta possa influenciar a determinação, validade, interpretação ou utilização legal do resultado da medição."}, {"c": "dou-paragraph", "t": "1.11 Estado do processo de medição"}, {"c": "dou-paragraph", "t": "Conjunto de dados e informações necessários para caracterizar o estado corrente de uma operação de totalização e permitir, quando aplicável, sua recuperação ou continuidade de forma metrologicamente válida após uma interrupção ou falha."}, {"c": "dou-paragraph", "t": "1.12 Falha legalmente relevante"}, {"c": "dou-paragraph", "t": "Falha de componente, função ou processo que possa comprometer funções, dados, parâmetros ou resultados legalmente relevantes ou a validade metrológica da medição."}, {"c": "dou-paragraph", "t": "1.13 Função legalmente relevante"}, {"c": "dou-paragraph", "t": "Função executada pelo instrumento que esteja sujeita ao controle metrológico legal ou que possa influenciar o atendimento aos requisitos metrológicos aplicáveis."}, {"c": "dou-paragraph", "t": "1.14 Identificação do software"}, {"c": "dou-paragraph", "t": "Sequência de caracteres, número, código ou outra informação vinculada ao software que permita identificar inequivocamente o software ou sua versão e estabelecer sua correspondência com a configuração aprovada."}, {"c": "dou-paragraph", "t": "1.15 Influência inadmissível"}, {"c": "dou-paragraph", "t": "Influência exercida sobre função, software, dado, parâmetro, configuração ou resultado legalmente relevante que possa comprometer o atendimento aos requisitos metrológicos aplicáveis ou a validade metrológica da medição."}, {"c": "dou-paragraph", "t": "1.16 Integridade"}, {"c": "dou-paragraph", "t": "Propriedade de software, dados, parâmetros ou outros elementos pela qual se pode assegurar ou verificar que não sofreram alteração ou substituição não autorizada ou não detectada."}, {"c": "dou-paragraph", "t": "1.17 Interface"}, {"c": "dou-paragraph", "t": "Fronteira física ou lógica entre componentes de hardware ou software por meio da qual são trocados dados, comandos ou outras informações ou são realizadas interações."}, {"c": "dou-paragraph", "t": "1.18 Interface de separação"}, {"c": "dou-paragraph", "t": "Interface definida entre software legalmente relevante e software legalmente não relevante, por meio da qual ocorre a comunicação entre essas partes e cuja implementação impede que a parte legalmente não relevante exerça influência inadmissível sobre a parte legalmente relevante."}, {"c": "dou-paragraph", "t": "1.19 Intervenção legalmente relevante"}, {"c": "dou-paragraph", "t": "Operação ou ação que altere ou possa alterar software, parâmetros, configurações ou outros elementos legalmente relevantes do instrumento."}, {"c": "dou-paragraph", "t": "1.20 Marca temporal (timestamp)"}, {"c": "dou-paragraph", "t": "Informação associada a um dado, registro, evento ou operação que representa a data, a hora ou outra referência temporal correspondente à sua ocorrência."}, {"c": "dou-paragraph", "t": "1.21 Massa totalizada"}, {"c": "dou-paragraph", "t": "Valor acumulado das massas das cargas determinadas e incorporadas ao resultado durante uma operação de totalização."}, {"c": "dou-paragraph", "t": "1.22 Parâmetro legalmente relevante"}, {"c": "dou-paragraph", "t": "Parâmetro de software ou de configuração cuja alteração possa influenciar uma função, dado ou resultado legalmente relevante."}, {"c": "dou-paragraph", "t": "1.23 Plataforma de propósito geral"}, {"c": "dou-paragraph", "t": "Plataforma computacional não destinada exclusivamente à execução das funções metrológicas do instrumento e capaz de executar software ou serviços para outras finalidades."}, {"c": "dou-paragraph", "t": "1.24 Proteção metrológica"}, {"c": "dou-paragraph", "t": "Meio físico, lógico ou combinação de meios destinado a impedir ou evidenciar acesso, modificação, substituição ou intervenção não autorizada em elementos legalmente relevantes."}, {"c": "dou-paragraph", "t": "1.25 Restrições de tempo de execução"}, {"c": "dou-paragraph", "t": "Condições relativas ao tempo de processamento ou de resposta que devem ser atendidas durante a execução de funções de software para assegurar seu correto funcionamento."}, {"c": "dou-paragraph", "t": "1.26 Resultado legalmente relevante"}, {"c": "dou-paragraph", "t": "Resultado da medição destinado a utilização para finalidade sujeita ao controle metrológico legal."}, {"c": "dou-paragraph", "t": "1.27 Separação de software"}, {"c": "dou-paragraph", "t": "Organização do software na qual as partes legalmente relevante e legalmente não relevante são separadas de forma que a parte legalmente não relevante não possa exercer influência inadmissível sobre funções, dados, parâmetros ou resultados legalmente relevantes."}, {"c": "dou-paragraph", "t": "1.28 Software legalmente não relevante"}, {"c": "dou-paragraph", "t": "Software, ou parte de software, que não implementa, executa ou participa de funções legalmente relevantes e cuja alteração ou funcionamento não possa exercer influência inadmissível sobre funções, dados, parâmetros ou resultados legalmente relevantes."}, {"c": "dou-paragraph", "t": "1.29 Software legalmente relevante"}, {"c": "dou-paragraph", "t": "Software, ou parte de software, que implementa, executa ou participa de funções legalmente relevantes, ou cuja alteração ou funcionamento possa exercer influência inadmissível sobre funções, dados, parâmetros ou resultados legalmente relevantes."}, {"c": "dou-paragraph", "t": "1.30 Transmissão de dados legalmente relevantes"}, {"c": "dou-paragraph", "t": "Transferência de dados legalmente relevantes entre componentes, dispositivos ou sistemas por meio de interface ou canal de comunicação."}, {"c": "dou-paragraph", "t": "1.31 Trilha de auditoria"}, {"c": "dou-paragraph", "t": "Conjunto contínuo e protegido de registros, associados à data e hora de ocorrência, destinado a documentar intervenções, alterações ou outros eventos legalmente relevantes necessários à rastreabilidade metrológica."}, {"c": "dou-paragraph", "t": "1.32 Verificação remota"}, {"c": "dou-paragraph", "t": "Execução, total ou parcial, de procedimentos destinados à verificação de características legalmente relevantes do instrumento sem acesso físico direto a ele, mediante comunicação remota."}, {"c": "dou-paragraph", "t": "2. Requisitos Gerais"}, {"c": "dou-paragraph", "t": "O software legalmente relevante do instrumento deve satisfazer à totalidade dos requisitos gerais estabelecidos nesta seção."}, {"c": "dou-paragraph", "t": "2.1 Delimitação do software legalmente relevante"}, {"c": "dou-paragraph", "t": "2.1 Delimitação do software legalmente relevante"}, {"c": "dou-paragraph", "t": "2.1.1 O software legalmente relevante deve compreender todos os componentes de software que executem funções legalmente relevantes ou cuja alteração ou funcionamento possa exercer influência inadmissível sobre funções, dados, parâmetros ou resultados legalmente relevantes."}, {"c": "dou-paragraph", "t": "2.1.2 Devem ser considerados legalmente relevantes, quando aplicáveis, os componentes de software envolvidos:"}, {"c": "dou-paragraph", "t": "a) na aquisição e no tratamento dos sinais provenientes dos transdutores e sensores;"}, {"c": "dou-paragraph", "t": "b) no controle e na determinação das fases do ciclo de pesagem;"}, {"c": "dou-paragraph", "t": "c) na determinação da massa de cada carga;"}, {"c": "dou-paragraph", "t": "d) na aplicação de correções e compensações;"}, {"c": "dou-paragraph", "t": "e) na determinação e aplicação do zero;"}, {"c": "dou-paragraph", "t": "f) na acumulação dos valores de massa e determinação da massa totalizada;"}, {"c": "dou-paragraph", "t": "g) na manutenção e recuperação do estado do processo de medição;"}, {"c": "dou-paragraph", "t": "h) na detecção e tratamento de falhas;"}, {"c": "dou-paragraph", "t": "i) na validação da operação de pesagem e totalização;"}, {"c": "dou-paragraph", "t": "j) na formação, apresentação, armazenamento ou transmissão do resultado legalmente relevante; e"}, {"c": "dou-paragraph", "t": "k) na proteção, identificação, verificação de integridade ou rastreabilidade de software, parâmetros e dados legalmente relevantes."}, {"c": "dou-paragraph", "t": "2.1.3 Devem integrar a delimitação da parte legalmente relevante os arquivos, bibliotecas, serviços e demais componentes de software necessários à execução das funções previstas em 2.1.2 quando sua alteração ou funcionamento puder exercer influência inadmissível sobre função, dado, parâmetro ou resultado legalmente relevante."}, {"c": "dou-paragraph", "t": "2.1.4 A delimitação do software legalmente relevante deve ser claramente definida e documentada pelo requerente do processo de aprovação de modelo, incluindo seus componentes, funções, dependências e interfaces com componentes não legalmente relevantes."}, {"c": "dou-paragraph", "t": "2.2 Identificação do software legalmente relevante"}, {"c": "dou-paragraph", "t": "2.2.1 O software legalmente relevante deve possuir identificação inequívoca. Quando constituído por componentes ou módulos identificáveis separadamente, estes devem possuir identificação individual, quando necessária para determinar inequivocamente a configuração de software legalmente relevante instalada no instrumento."}, {"c": "dou-paragraph", "t": "2.2.2 A identificação deve estar vinculada ao software ao qual se refere e deve poder ser obtida durante as atividades de controle metrológico legal, por meio do instrumento ou de procedimento apropriado definido na aprovação de modelo."}, {"c": "dou-paragraph", "t": "2.2.3 A identificação deve permitir verificar inequivocamente a correspondência entre o software instalado e aquele que foi aprovado."}, {"c": "dou-paragraph", "t": "2.2.4 Qualquer alteração do software legalmente relevante deve resultar em identificação diferente daquela correspondente à versão anteriormente identificada."}, {"c": "dou-paragraph", "t": "2.2.5 A identificação do software legalmente relevante deve ser disponibilizada de forma inequívoca durante as atividades de controle metrológico legal e não deve ser confundida com identificações de software legalmente não relevante."}, {"c": "dou-paragraph", "t": "2.3 Correção das funções e algoritmos legalmente relevantes"}, {"c": "dou-paragraph", "t": "2.3.1 As funções e algoritmos legalmente relevantes devem ser adequados à finalidade metrológica do instrumento e devem estar corretamente implementados para as condições de utilização previstas."}, {"c": "dou-paragraph", "t": "2.3.2 Deve ser possível examinar a correção dos algoritmos e funções legalmente relevantes por meio de ensaios metrológicos, ensaios funcionais de software, análise documental, análise de código-fonte e/ou combinação desses métodos."}, {"c": "dou-paragraph", "t": "2.3.3 Para fins do disposto nesta seção, devem ser considerados, quando aplicáveis, os algoritmos e funções relacionados:"}, {"c": "dou-paragraph", "t": "a) à aquisição e ao tratamento dos sinais;"}, {"c": "dou-paragraph", "t": "b) à filtragem de sinais;"}, {"c": "dou-paragraph", "t": "c) ao controle e à determinação das fases do ciclo de pesagem;"}, {"c": "dou-paragraph", "t": "d) à determinação da massa de cada carga;"}, {"c": "dou-paragraph", "t": "e) à determinação e aplicação do zero;"}, {"c": "dou-paragraph", "t": "f) às correções e compensações;"}, {"c": "dou-paragraph", "t": "g) ao arredondamento;"}, {"c": "dou-paragraph", "t": "h) à acumulação dos valores de massa e determinação da massa totalizada;"}, {"c": "dou-paragraph", "t": "i) à manutenção e recuperação do estado do processo de medição; e"}, {"c": "dou-paragraph", "t": "j) à determinação das condições de validade da operação de pesagem e totalização."}, {"c": "dou-paragraph", "t": "2.3.4 As condições que determinem a validade de uma operação de pesagem e totalização devem estar definidas. Quando não estiverem satisfeitas as condições necessárias à validade da medição estabelecidas na aprovação de modelo, o instrumento não deve disponibilizar o resultado como legalmente válido."}, {"c": "dou-paragraph", "t": "2.4 Proteção do software legalmente relevante"}, {"c": "dou-paragraph", "t": "2.4.1 O software legalmente relevante deve ser protegido contra modificação ou substituição acidental ou não autorizada."}, {"c": "dou-paragraph", "t": "2.4.2 Os mecanismos de proteção devem ser adequados às formas pelas quais o software possa ser acessado, modificado ou substituído."}, {"c": "dou-paragraph", "t": "2.4.3 Intervenções não autorizadas no software legalmente relevante devem ser impedidas ou detectadas, de forma que funções, dados, parâmetros ou resultados legalmente relevantes não sejam comprometidos."}, {"c": "dou-paragraph", "t": "2.4.4 Quando for detectada condição que comprometa ou impeça a comprovação da integridade do software legalmente relevante, o instrumento não deve produzir ou disponibilizar resultado como legalmente válido."}, {"c": "dou-paragraph", "t": "2.4.5 Deve ser possível verificar a integridade do software legalmente relevante em relação à configuração aprovada."}, {"c": "dou-paragraph", "t": "2.5 Proteção dos parâmetros legalmente relevantes"}, {"c": "dou-paragraph", "t": "2.5.1 Os parâmetros legalmente relevantes devem ser protegidos contra alteração acidental ou não autorizada."}, {"c": "dou-paragraph", "t": "2.5.2 Os mecanismos de proteção devem considerar todos os meios pelos quais os parâmetros possam ser inseridos, alterados ou substituídos."}, {"c": "dou-paragraph", "t": "2.5.3 Quando sua alteração puder influenciar função, dado ou resultado legalmente relevante, devem ser considerados legalmente relevantes os parâmetros utilizados:"}, {"c": "dou-paragraph", "t": "a) na calibração;"}, {"c": "dou-paragraph", "t": "b) na correção e compensação;"}, {"c": "dou-paragraph", "t": "c) na filtragem e no tratamento dos sinais;"}, {"c": "dou-paragraph", "t": "d) na determinação da massa;"}, {"c": "dou-paragraph", "t": "e) na determinação e aplicação do zero;"}, {"c": "dou-paragraph", "t": "f) no controle e na determinação das fases do ciclo de pesagem;"}, {"c": "dou-paragraph", "t": "g) na acumulação e totalização dos valores de massa; e"}, {"c": "dou-paragraph", "t": "h) na validação da operação de pesagem e totalização."}, {"c": "dou-paragraph", "t": "2.5.4 A alteração de parâmetro legalmente relevante somente deve ser possível de forma autorizada e nas condições e limites estabelecidos na aprovação de modelo."}, {"c": "dou-paragraph", "t": "2.5.5 Os valores ou as identificações dos parâmetros legalmente relevantes devem ser passíveis de verificação durante as atividades de controle metrológico legal."}, {"c": "dou-paragraph", "t": "2.5.6 Quando a integridade de parâmetro necessário à execução de função legalmente relevante não puder ser assegurada, o parâmetro não deve ser utilizado para produzir resultado legalmente válido."}, {"c": "dou-paragraph", "t": "2.6 Proteção dos dados legalmente relevantes"}, {"c": "dou-paragraph", "t": "2.6.1 Os dados legalmente relevantes devem ter sua integridade e, quando aplicável, sua autenticidade e associação inequívoca asseguradas ao longo da cadeia metrológica."}, {"c": "dou-paragraph", "t": "2.6.2 Para fins do disposto nesta seção, devem ser considerados, quando legalmente relevantes:"}, {"c": "dou-paragraph", "t": "a) os dados provenientes dos módulos de aquisição;"}, {"c": "dou-paragraph", "t": "b) os dados intermediários necessários à determinação da massa;"}, {"c": "dou-paragraph", "t": "c) os dados que caracterizam as fases do ciclo de pesagem;"}, {"c": "dou-paragraph", "t": "d) o valor da massa determinada em cada ciclo de pesagem;"}, {"c": "dou-paragraph", "t": "e) os dados relativos ao estado corrente do processo de medição;"}, {"c": "dou-paragraph", "t": "f) os resultados intermediários legalmente relevantes;"}, {"c": "dou-paragraph", "t": "g) o valor acumulado da massa;"}, {"c": "dou-paragraph", "t": "h) o resultado final da totalização;"}, {"c": "dou-paragraph", "t": "i) a identificação da operação de totalização; e"}, {"c": "dou-paragraph", "t": "j) as informações necessárias à associação inequívoca entre os dados e a respectiva operação de totalização."}, {"c": "dou-paragraph", "t": "2.6.3 Quando a integridade ou, quando requerida, a autenticidade ou associação inequívoca de dado necessário à execução de função legalmente relevante não puder ser assegurada, esse dado não deve ser utilizado para produzir resultado legalmente válido."}, {"c": "dou-paragraph", "t": "2.6.4 Os mecanismos de proteção devem permitir detectar alterações ou substituições de dados que possam comprometer função ou resultado legalmente relevante."}, {"c": "dou-paragraph", "t": "2.7 Composição do resultado da medição"}, {"c": "dou-paragraph", "t": "2.7.1 O resultado legalmente relevante deve compreender o valor da massa totalizada e as informações necessárias à sua correta interpretação e à associação inequívoca à respectiva operação de totalização."}, {"c": "dou-paragraph", "t": "2.7.2 O resultado deve conter, no mínimo:"}, {"c": "dou-paragraph", "t": "a) valor da massa totalizada;"}, {"c": "dou-paragraph", "t": "b) unidade de medida;"}, {"c": "dou-paragraph", "t": "c) identificação inequívoca da operação de totalização;"}, {"c": "dou-paragraph", "t": "d) data e hora associadas à operação de totalização, quando aplicável; e"}, {"c": "dou-paragraph", "t": "e) identificação do instrumento."}, {"c": "dou-paragraph", "t": "2.7.3 Outras informações necessárias à correta interpretação ou utilização do resultado devem integrá-lo ou permanecer inequivocamente associadas a ele, conforme estabelecido na aprovação de modelo."}, {"c": "dou-paragraph", "t": "2.7.4 As informações que compõem o resultado devem permanecer inequivocamente associadas entre si."}, {"c": "dou-paragraph", "t": "2.7.5 Informações que não integrem o resultado legalmente relevante, quando apresentadas ou disponibilizadas juntamente com este, devem ser claramente distinguíveis das informações que o compõem."}, {"c": "dou-paragraph", "t": "2.8 Registro e rastreabilidade das intervenções"}, {"c": "dou-paragraph", "t": "2.8.1 As intervenções autorizadas que possam alterar software, parâmetros, configurações ou outros elementos legalmente relevantes, quando realizadas sem rompimento de proteção física metrologicamente controlada, devem ser registradas em trilha de auditoria protegida."}, {"c": "dou-paragraph", "t": "2.8.2 O registro de auditoria deve permitir identificar inequivocamente, no mínimo:"}, {"c": "dou-paragraph", "t": "a) o tipo de intervenção realizada;"}, {"c": "dou-paragraph", "t": "b) o elemento legalmente relevante afetado;"}, {"c": "dou-paragraph", "t": "c) a data e hora da intervenção;"}, {"c": "dou-paragraph", "t": "d) identificação do responsável, entidade, processo ou nível de autorização, conforme aplicável;"}, {"c": "dou-paragraph", "t": "e) o valor ou identificação anterior, quando aplicável;"}, {"c": "dou-paragraph", "t": "f) o valor ou identificação posterior, quando aplicável; e"}, {"c": "dou-paragraph", "t": "g) o resultado da intervenção, quando aplicável."}, {"c": "dou-paragraph", "t": "2.8.3 Os registros de auditoria devem ser protegidos contra alteração e exclusão não autorizadas."}, {"c": "dou-paragraph", "t": "2.8.4 A trilha de auditoria deve possuir capacidade adequada ao uso previsto do instrumento. A eliminação ou sobrescrita de registros deve ocorrer somente de forma controlada, sem comprometer a rastreabilidade exigida para as atividades de controle metrológico legal."}, {"c": "dou-paragraph", "t": "2.8.5 O esgotamento da capacidade de armazenamento do registro de auditoria não deve resultar na perda não controlada de registros legalmente relevantes."}, {"c": "dou-paragraph", "t": "2.8.6 Os registros devem poder ser obtidos e interpretados durante as atividades de controle metrológico legal, por meio do instrumento ou de procedimento apropriado estabelecido na aprovação de modelo."}, {"c": "dou-paragraph", "t": "2.9 Detecção e tratamento de falhas e preservação do estado da medição"}, {"c": "dou-paragraph", "t": "2.9.1 Devem ser implementados meios adequados para detectar falhas que possam comprometer funções, dados, parâmetros ou resultados legalmente relevantes, quando sua detecção pelo instrumento for necessária para assegurar a validade metrológica."}, {"c": "dou-paragraph", "t": "2.9.2 Quando detectada falha que possa comprometer a validade da medição, o instrumento deve interromper a operação de pesagem ou totalização, impedir a utilização do resultado como legalmente válido ou adotar outro comportamento seguro definido na aprovação de modelo."}, {"c": "dou-paragraph", "t": "2.9.3 Devem ser consideradas, quando aplicáveis, falhas relacionadas:"}, {"c": "dou-paragraph", "t": "a) aos sensores ou transdutores;"}, {"c": "dou-paragraph", "t": "b) à aquisição ou tratamento dos sinais;"}, {"c": "dou-paragraph", "t": "c) ao controle ou à sequência das fases do ciclo de pesagem;"}, {"c": "dou-paragraph", "t": "d) à determinação da massa;"}, {"c": "dou-paragraph", "t": "e) à acumulação dos valores de massa;"}, {"c": "dou-paragraph", "t": "f) à comunicação entre módulos legalmente relevantes;"}, {"c": "dou-paragraph", "t": "g) à integridade dos dados legalmente relevantes;"}, {"c": "dou-paragraph", "t": "h) à execução das funções de cálculo;"}, {"c": "dou-paragraph", "t": "i) à alimentação elétrica ou à interrupção da execução do software; e"}, {"c": "dou-paragraph", "t": "j) à validação do resultado."}, {"c": "dou-paragraph", "t": "2.9.4 As reações às falhas detectadas devem ser definidas de forma a impedir que a falha resulte em utilização metrologicamente indevida do instrumento ou de seus resultados."}, {"c": "dou-paragraph", "t": "2.9.5 Quando uma falha ou perturbação puder interromper uma operação de totalização em curso, os dados legalmente relevantes e as informações necessárias à determinação do estado corrente do processo de medição devem ser preservados de forma a impedir perda, duplicação ou alteração não controlada do valor acumulado da massa."}, {"c": "dou-paragraph", "t": "2.9.6 Os dados necessários à preservação do valor acumulado da massa e do estado corrente do processo de medição devem ser mantidos por meio que assegure sua conservação e recuperação de forma metrologicamente segura."}, {"c": "dou-paragraph", "t": "2.9.7 Após uma interrupção ou falha, o instrumento somente deve permitir a continuidade ou recuperação da operação de totalização quando puder ser assegurada a consistência entre os dados recuperados, o estado do processo de medição e o valor acumulado da massa."}, {"c": "dou-paragraph", "t": "2.9.8 Quando a consistência prevista em 2.9.7 não puder ser assegurada, o instrumento deve impedir que o resultado correspondente seja utilizado como legalmente válido ou adotar outro comportamento seguro definido na aprovação de modelo."}, {"c": "dou-paragraph", "t": "2.9.9 O tratamento de falhas e a recuperação do processo de medição devem impedir que a massa correspondente a um ciclo de pesagem seja indevidamente omitida ou incorporada mais de uma vez ao valor acumulado da massa."}, {"c": "dou-paragraph", "t": "2.10 Relógio e referência temporal"}, {"c": "dou-paragraph", "t": "2.10.1 Quando data, hora ou marca temporal forem utilizadas na composição do resultado da medição, na trilha de auditoria ou em outra função legalmente relevante, a referência temporal utilizada deve ser fornecida por mecanismo adequado à finalidade metrológica."}, {"c": "dou-paragraph", "t": "2.10.2 A alteração da data ou hora, quando puder influenciar informação ou função legalmente relevante, deve ser protegida contra alteração não autorizada."}, {"c": "dou-paragraph", "t": "2.10.3 As alterações autorizadas da referência temporal que possam influenciar função, dado, registro ou resultado legalmente relevante devem ser registradas na trilha de auditoria, incluindo as informações necessárias à identificação da alteração realizada."}, {"c": "dou-paragraph", "t": "2.10.4 Quando houver sincronização automática do relógio por fonte externa, devem ser adotados meios adequados para assegurar a autenticidade da referência temporal utilizada e impedir influência inadmissível sobre funções ou informações legalmente relevantes."}, {"c": "dou-paragraph", "t": "2.10.5 A indisponibilidade ou falha da referência temporal não deve resultar na produção ou disponibilização de resultado legalmente válido quando a informação temporal for necessária à validade ou à correta interpretação da medição."}, {"c": "dou-paragraph", "t": "2.10.6 Quando a referência temporal for necessária à validade da medição ou à correta interpretação do resultado, e não puder ser estabelecida ou mantida de forma adequada, o instrumento não deve produzir ou disponibilizar o resultado como legalmente válido."}, {"c": "dou-paragraph", "t": "2.11 Documentação requerida para os requisitos gerais"}, {"c": "dou-paragraph", "t": "2.11.1 O requerente do processo de aprovação de modelo deve fornecer documentação técnica suficiente para permitir a compreensão do funcionamento do instrumento e a avaliação do atendimento aos requisitos gerais aplicáveis deste Anexo."}, {"c": "dou-paragraph", "t": "2.11.2 A documentação deve conter, quando aplicável:"}, {"c": "dou-paragraph", "t": "a) descrição funcional do instrumento e do software;"}, {"c": "dou-paragraph", "t": "b) descrição da cadeia metrológica legalmente relevante, identificando os componentes, funções, dados, parâmetros e interfaces envolvidos desde a aquisição até a formação do resultado;"}, {"c": "dou-paragraph", "t": "c) descrição da arquitetura de hardware e software relevante à avaliação;"}, {"c": "dou-paragraph", "t": "d) delimitação do software legalmente relevante, incluindo seus componentes, funções, dependências e interfaces;"}, {"c": "dou-paragraph", "t": "e) descrição das funções e algoritmos legalmente relevantes;"}, {"c": "dou-paragraph", "t": "f) identificação dos dados e parâmetros legalmente relevantes e descrição de sua utilização;"}, {"c": "dou-paragraph", "t": "g) identificação da configuração de software legalmente relevante submetida à aprovação;"}, {"c": "dou-paragraph", "t": "h) descrição dos mecanismos de proteção do software, parâmetros e dados legalmente relevantes;"}, {"c": "dou-paragraph", "t": "i) descrição da composição, formação e apresentação do resultado legalmente relevante;"}, {"c": "dou-paragraph", "t": "j) descrição dos mecanismos de registro e rastreabilidade das intervenções;"}, {"c": "dou-paragraph", "t": "k) descrição dos mecanismos de detecção e tratamento de falhas, incluindo os mecanismos utilizados para preservação e recuperação do valor acumulado da massa e do estado do processo de medição;"}, {"c": "dou-paragraph", "t": "l) descrição das interfaces relevantes à cadeia metrológica;"}, {"c": "dou-paragraph", "t": "m) evidências técnicas necessárias à demonstração do atendimento aos requisitos aplicáveis;"}, {"c": "dou-paragraph", "t": "n) descrição dos mecanismos utilizados para estabelecimento e manutenção da referência temporal, incluindo, quando aplicável, fonte de tempo, sincronização, ajuste, proteção, registro de alterações e tratamento de falhas; e"}, {"c": "dou-paragraph", "t": "o) descrição das condições e procedimentos utilizados para recuperação ou continuidade da operação de totalização após interrupção ou falha, incluindo as medidas utilizadas para impedir perda ou duplicação de valores no resultado acumulado."}, {"c": "dou-paragraph", "t": "3. Requisitos Específicos"}, {"c": "dou-paragraph", "t": "O software e o hardware legalmente relevantes que empregarem as funcionalidades ou arquiteturas descritas nesta seção devem satisfazer à totalidade dos respectivos requisitos específicos aplicáveis."}, {"c": "dou-paragraph", "t": "3.1 Separação de software"}, {"c": "dou-paragraph", "t": "3.1.1 Quando software legalmente relevante e software legalmente não relevante coexistirem no instrumento, a separação deve assegurar que a parte legalmente não relevante não exerça influência inadmissível sobre funções, dados, parâmetros ou resultados legalmente relevantes."}, {"c": "dou-paragraph", "t": "3.1.2 As funções legalmente relevantes e o processamento de dados e parâmetros capazes de influenciar funções ou resultados legalmente relevantes devem permanecer sob controle da parte legalmente relevante."}, {"c": "dou-paragraph", "t": "3.1.3 A comunicação entre as partes legalmente relevante e não relevante deve ocorrer exclusivamente por interfaces de separação definidas e deve ser controlada pela parte legalmente relevante."}, {"c": "dou-paragraph", "t": "3.1.4 Somente comandos, dados e funções definidos e documentados devem ser admitidos através da interface de separação."}, {"c": "dou-paragraph", "t": "3.1.5 Os comandos admitidos pela interface de separação devem possuir efeitos definidos e documentados sobre a parte legalmente relevante."}, {"c": "dou-paragraph", "t": "3.1.6 Comandos, dados ou condições não previstos que forem recebidos através da interface de separação não devem produzir influência inadmissível sobre a parte legalmente relevante."}, {"c": "dou-paragraph", "t": "3.1.7 Alterações na parte legalmente não relevante não devem comprometer a separação nem produzir influência inadmissível sobre a parte legalmente relevante."}, {"c": "dou-paragraph", "t": "3.1.8 Quando não puder ser demonstrado que a separação atende aos requisitos desta seção, todo o software deve ser considerado legalmente relevante."}, {"c": "dou-paragraph", "t": "3.2 Controle de acesso a funções legalmente relevantes"}, {"c": "dou-paragraph", "t": "3.2.1 O acesso a funções capazes de alterar software, parâmetros, configurações ou outros elementos legalmente relevantes, quando possível sem rompimento de proteção física metrologicamente controlada, deve ser restrito a pessoas, entidades ou processos autorizados."}, {"c": "dou-paragraph", "t": "3.2.2 Os mecanismos de controle de acesso devem ser adequados à natureza e ao risco metrológico das funções protegidas."}, {"c": "dou-paragraph", "t": "3.2.3 Quando a autorização requerida não puder ser estabelecida, a execução da função protegida deve ser impedida."}, {"c": "dou-paragraph", "t": "3.2.4 Os mecanismos e informações utilizados para estabelecer a autorização devem ser protegidos contra utilização, alteração, substituição ou divulgação não autorizada, conforme aplicável."}, {"c": "dou-paragraph", "t": "3.3 Armazenamento de dados legalmente relevantes"}, {"c": "dou-paragraph", "t": "3.3.1 Quando dados legalmente relevantes forem armazenados para posterior utilização legalmente relevante, sua integridade e associação devem ser asseguradas durante o período de armazenamento e, quando necessário, também sua autenticidade."}, {"c": "dou-paragraph", "t": "3.3.2 Os dados armazenados devem conter ou permanecer inequivocamente associados às informações necessárias à sua correta interpretação e utilização legal."}, {"c": "dou-paragraph", "t": "3.3.3 A integridade e, quando aplicável, a autenticidade e a associação dos dados recuperados devem ser verificáveis antes de sua utilização legalmente relevante."}, {"c": "dou-paragraph", "t": "3.3.4 Quando não puderem ser asseguradas as propriedades requeridas no item 3.3.3, os dados recuperados não devem ser utilizados para produzir, reconstruir ou disponibilizar resultado como legalmente válido."}, {"c": "dou-paragraph", "t": "3.3.5 O sistema de armazenamento deve possuir capacidade e características adequadas para assegurar a conservação dos dados pelo período requerido para sua utilização legalmente relevante."}, {"c": "dou-paragraph", "t": "3.3.6 Quando necessário à utilização legal dos dados, deve ser possível reconstruir inequivocamente a associação entre os dados armazenados, a respectiva operação de totalização e o resultado correspondente."}, {"c": "dou-paragraph", "t": "3.4 Transmissão de dados legalmente relevantes"}, {"c": "dou-paragraph", "t": "3.4.1 Quando dados legalmente relevantes forem transmitidos por rede ou canal de comunicação, devem ser adotados meios para assegurar sua integridade, autenticidade e associação inequívoca à respectiva operação de totalização."}, {"c": "dou-paragraph", "t": "3.4.2 Os dados transmitidos devem conter ou permanecer inequivocamente associados às informações necessárias à sua correta interpretação e utilização legal."}, {"c": "dou-paragraph", "t": "3.4.3 Alterações ou substituições dos dados durante a transmissão que possam comprometer sua utilização legal devem ser detectáveis."}, {"c": "dou-paragraph", "t": "3.4.4 Quando não puderem ser asseguradas a integridade ou, quando requeridas, a autenticidade e a associação dos dados recebidos, estes não devem ser utilizados para produzir, reconstruir ou disponibilizar resultado como legalmente válido."}, {"c": "dou-paragraph", "t": "3.4.5 Quando necessário para assegurar a utilização legal dos dados, devem ser detectáveis situações de repetição indevida, substituição, perda, reordenação ou associação incorreta."}, {"c": "dou-paragraph", "t": "3.4.6 Atrasos, interrupções ou falhas da comunicação não devem produzir influência inadmissível sobre funções, dados ou resultados legalmente relevantes."}, {"c": "dou-paragraph", "t": "3.4.7 Quando o canal de comunicação não fornecer as propriedades de segurança necessárias, os dados ou mensagens legalmente relevantes devem ser protegidos por mecanismos que assegurem as propriedades requeridas nesta seção."}, {"c": "dou-paragraph", "t": "3.5 Interfaces"}, {"c": "dou-paragraph", "t": "3.5.1 As interfaces que permitam comunicação ou interação com funções, dados, parâmetros ou outros elementos legalmente relevantes devem ser projetadas de forma a impedir influência inadmissível sobre a parte legalmente relevante."}, {"c": "dou-paragraph", "t": "3.5.2 As funções, comandos e dados admitidos por essas interfaces que possam produzir efeitos legalmente relevantes devem ser definidos e documentados, bem como seus efeitos sobre a parte legalmente relevante."}, {"c": "dou-paragraph", "t": "3.5.3 Não devem existir, por meio das interfaces acessíveis, funções ou comandos não documentados capazes de exercer influência inadmissível sobre elementos legalmente relevantes."}, {"c": "dou-paragraph", "t": "3.5.4 As interfaces que permitam acesso a funções sujeitas a controle de acesso devem atender aos requisitos de 3.2."}, {"c": "dou-paragraph", "t": "3.5.5 Os requisitos desta seção aplicam-se, conforme pertinente, às interfaces de comunicação, de usuário, de manutenção, de diagnóstico e de acesso remoto."}, {"c": "dou-paragraph", "t": "3.6 Atualização do software legalmente relevante"}, {"c": "dou-paragraph", "t": "3.6.1 Quando prevista a atualização do software legalmente relevante, o mecanismo de atualização e as condições para sua realização devem estar definidos e ser avaliados na aprovação de modelo."}, {"c": "dou-paragraph", "t": "3.6.2 A atualização que dependa do rompimento de proteção metrológica física deve somente ser realizada nas condições estabelecidas para intervenção no instrumento."}, {"c": "dou-paragraph", "t": "3.6.3 Quando a atualização puder ser realizada sem rompimento de proteção física metrologicamente controlada, o processo deve assegurar:"}, {"c": "dou-paragraph", "t": "a) que a atualização seja realizada somente mediante autorização;"}, {"c": "dou-paragraph", "t": "b) a autenticidade e a integridade do software a ser instalado;"}, {"c": "dou-paragraph", "t": "c) que a versão do software legalmente relevante a ser instalada tenha sido previamente aprovada pelo Inmetro para o modelo do instrumento; e"}, {"c": "dou-paragraph", "t": "d) a rastreabilidade da atualização."}, {"c": "dou-paragraph", "t": "3.6.4 O software atualizado somente deve ser ativado para utilização legalmente relevante após a verificação bem-sucedida das condições estabelecidas em 3.6.3."}, {"c": "dou-paragraph", "t": "3.6.5 A interrupção ou falha do processo de atualização não deve resultar na utilização de configuração de software legalmente relevante cuja integridade e admissibilidade não tenham sido estabelecidas."}, {"c": "dou-paragraph", "t": "3.6.6 Em caso de falha da atualização ou das verificações requeridas, deve ser mantida ou restaurada uma configuração legalmente relevante válida ou impedida a produção e disponibilização de resultados como legalmente válidos."}, {"c": "dou-paragraph", "t": "3.6.7 As atualizações realizadas devem ser registradas conforme 2.8, incluindo, quando aplicável, as identificações das configurações anterior e posterior e o resultado da atualização."}, {"c": "dou-paragraph", "t": "3.6.8 Os componentes responsáveis pela verificação e ativação da atualização do software legalmente relevante são considerados legalmente relevantes."}, {"c": "dou-paragraph", "t": "3.7 Sistemas operacionais e plataformas de propósito geral"}, {"c": "dou-paragraph", "t": "3.7.1 Quando o software legalmente relevante for executado em sistema operacional ou plataforma de propósito geral, a arquitetura e a configuração da plataforma devem assegurar que seus componentes legalmente não relevantes não exerçam influência inadmissível sobre funções, dados, parâmetros ou resultados legalmente relevantes."}, {"c": "dou-paragraph", "t": "3.7.2 Os componentes e configurações da plataforma que possam influenciar o funcionamento legalmente relevante devem ser identificados e controlados na extensão necessária para assegurar a conformidade do instrumento."}, {"c": "dou-paragraph", "t": "3.7.3 Quando o funcionamento correto do software legalmente relevante depender de determinada configuração, recurso ou condição do ambiente de execução, devem existir meios adequados para impedir a utilização legalmente relevante do instrumento quando essas condições não forem satisfeitas."}, {"c": "dou-paragraph", "t": "3.7.4 Quando aplicável, permissões e privilégios, serviços, bibliotecas, drivers e aplicações concorrentes que possam exercer influência sobre a parte legalmente relevante devem ser considerados, identificados e adequadamente controlados."}, {"c": "dou-paragraph", "t": "3.7.5 Alterações em componentes legalmente não relevantes não devem modificar a configuração legalmente relevante nem produzir influência inadmissível sobre seu funcionamento."}, {"c": "dou-paragraph", "t": "3.7.6 O compartilhamento de recursos computacionais e a execução concorrente de componentes legalmente não relevantes não devem comprometer o funcionamento das funções legalmente relevantes."}, {"c": "dou-paragraph", "t": "3.7.7 Quando o processo de inicialização do sistema puder influenciar a integridade ou a configuração do software legalmente relevante, esse processo deve ser protegido de forma a assegurar que somente configurações admissíveis sejam utilizadas para sua execução."}, {"c": "dou-paragraph", "t": "3.7.8 A configuração de inicialização capaz de influenciar o software legalmente relevante deve ser protegida contra alteração não autorizada."}, {"c": "dou-paragraph", "t": "3.7.9 A inicialização por interfaces ou fontes externas não deve permitir a execução de software ou configuração capaz de exercer influência inadmissível sobre a parte legalmente relevante."}, {"c": "dou-paragraph", "t": "3.8 Verificação remota dos requisitos de software"}, {"c": "dou-paragraph", "t": "3.8.1 Quando o instrumento possibilitar verificação remota dos requisitos de software, o procedimento deve permitir a execução segura e inequívoca das verificações previstas para essa finalidade e a obtenção das respectivas informações e resultados necessários às atividades de controle metrológico legal."}, {"c": "dou-paragraph", "t": "3.8.2 Devem ser disponibilizados, quando aplicáveis:"}, {"c": "dou-paragraph", "t": "a) identificação do instrumento;"}, {"c": "dou-paragraph", "t": "b) identificação do software legalmente relevante;"}, {"c": "dou-paragraph", "t": "c) configuração legalmente relevante;"}, {"c": "dou-paragraph", "t": "d) valores ou identificação dos parâmetros legalmente relevantes;"}, {"c": "dou-paragraph", "t": "e) registros de intervenções legalmente relevantes;"}, {"c": "dou-paragraph", "t": "f) evidências necessárias à verificação de integridade e autenticidade do software legalmente relevante; e"}, {"c": "dou-paragraph", "t": "g) resultados das funções ou procedimentos de verificação executados pelo instrumento."}, {"c": "dou-paragraph", "t": "3.8.3 As informações e os resultados obtidos remotamente devem ter sua autenticidade e integridade asseguradas e devem permanecer inequivocamente associados ao instrumento e, quando aplicável, à operação ou ao procedimento de verificação correspondente."}, {"c": "dou-paragraph", "t": "3.8.4 A comunicação utilizada para a verificação remota deve ser protegida contra acesso não autorizado e contra alteração, substituição ou associação incorreta das informações e comandos utilizados no procedimento."}, {"c": "dou-paragraph", "t": "3.8.5 O procedimento de verificação remota não deve possibilitar alteração não autorizada nem exercer influência inadmissível sobre software, funções, parâmetros, configurações, dados ou resultados legalmente relevantes."}, {"c": "dou-paragraph", "t": "3.8.6 O acesso remoto às funções de verificação deve ser restrito às entidades autorizadas."}, {"c": "dou-paragraph", "t": "3.8.7 A indisponibilidade da conexão ou a impossibilidade de execução da verificação remota não deve, por si só, comprometer as funções legalmente relevantes nem alterar a validade metrológica das medições realizadas pelo instrumento."}, {"c": "dou-paragraph", "t": "3.8.8 A verificação remota pode abranger a totalidade ou parte das verificações aplicáveis ao instrumento, conforme os procedimentos estabelecidos para o controle metrológico legal."}, {"c": "dou-paragraph", "t": "3.8.9 Quando a verificação remota produzir resultado utilizado para fins de controle metrológico legal, o instrumento deve permitir o registro protegido desse resultado e das informações necessárias à identificação inequívoca do procedimento realizado, incluindo, quando aplicável, identificação da entidade responsável e data e hora da verificação."}, {"c": "dou-paragraph", "t": "3.9 Comportamento dinâmico e recursos computacionais"}, {"c": "dou-paragraph", "t": "3.9.1 Os recursos computacionais necessários à execução das funções legalmente relevantes devem ser suficientes para assegurar seu correto funcionamento nas condições de utilização previstas para o instrumento."}, {"c": "dou-paragraph", "t": "3.9.2 A execução concorrente de software, serviços, processos ou outras funções não deve provocar atrasos, interrupções, perda de dados, perda de eventos ou outras condições capazes de exercer influência inadmissível sobre funções, dados, parâmetros ou resultados legalmente relevantes."}, {"c": "dou-paragraph", "t": "3.9.3 O compartilhamento de recursos computacionais, incluindo recursos de processamento, memória, armazenamento, entrada e saída e comunicação, não deve comprometer o funcionamento das funções legalmente relevantes."}, {"c": "dou-paragraph", "t": "3.9.4 Quando o correto funcionamento das funções legalmente relevantes depender do processamento de dados ou da execução de operações dentro de intervalos de tempo determinados, as condições necessárias ao correto processamento devem ser identificadas e consideradas na avaliação de modelo."}, {"c": "dou-paragraph", "t": "3.9.5 Quando a insuficiência ou indisponibilidade de recursos computacionais puder comprometer a validade da medição, essa condição deve ser detectada, quando tecnicamente aplicável, e o instrumento deve impedir a utilização do resultado como legalmente válido ou adotar outro comportamento seguro definido na aprovação de modelo."}, {"c": "dou-paragraph", "t": "3.9.6 A execução das funções legalmente relevantes deve assegurar que atrasos, interrupções, perda, repetição ou processamento incorreto de dados ou eventos não resultem em omissão ou duplicação indevida de valores na determinação da massa totalizada."}, {"c": "dou-paragraph", "t": "3.10 Documentação requerida para os requisitos específicos"}, {"c": "dou-paragraph", "t": "3.10.1 Quando aplicáveis os requisitos específicos desta seção, o requerente deve fornecer, além da documentação prevista em 2.11, as informações necessárias à avaliação das respectivas funcionalidades e arquiteturas."}, {"c": "dou-paragraph", "t": "3.10.2 Para a separação de software, devem ser documentadas a arquitetura das partes legalmente relevante e não legalmente relevante, suas interfaces e os mecanismos utilizados para impedir influência inadmissível sobre a parte legalmente relevante."}, {"c": "dou-paragraph", "t": "3.10.3 Para controle de acesso, devem ser fornecidas a descrição das funções protegidas, dos níveis de acesso, dos mecanismos de autorização e das medidas de proteção das credenciais ou elementos equivalentes."}, {"c": "dou-paragraph", "t": "3.10.4 Para armazenamento ou transmissão de dados, devem ser fornecidas a descrição dos dados, formatos, meios, protocolos e mecanismos utilizados para garantir as propriedades de segurança requeridas."}, {"c": "dou-paragraph", "t": "3.10.5 Para interfaces, devem ser fornecidas:"}, {"c": "dou-paragraph", "t": "a) descrição funcional das interfaces;"}, {"c": "dou-paragraph", "t": "b) relação completa das funções e comandos disponíveis;"}, {"c": "dou-paragraph", "t": "c) descrição dos efeitos de cada função ou comando sobre elementos legalmente relevantes; e"}, {"c": "dou-paragraph", "t": "d) mecanismos de proteção implementados."}, {"c": "dou-paragraph", "t": "3.10.6 Para atualização do software legalmente relevante, devem ser fornecidas:"}, {"c": "dou-paragraph", "t": "a) descrição do procedimento de atualização;"}, {"c": "dou-paragraph", "t": "b) mecanismos de autorização;"}, {"c": "dou-paragraph", "t": "c) mecanismos de verificação de autenticidade e integridade;"}, {"c": "dou-paragraph", "t": "d) mecanismo utilizado para assegurar a instalação somente de versões autorizadas;"}, {"c": "dou-paragraph", "t": "e) tratamento de falhas durante a atualização; e"}, {"c": "dou-paragraph", "t": "f) estrutura e forma de disponibilização dos respectivos registros."}, {"c": "dou-paragraph", "t": "3.10.7 Para a verificação remota dos requisitos de software, devem ser documentados sua arquitetura, funcionalidades, interfaces, informações utilizadas e mecanismos empregados para atendimento ao item 3.8."}, {"c": "dou-paragraph", "t": "3.10.8 Para sistemas operacionais ou plataformas de propósito geral, devem ser documentados os componentes, configurações, dependências e recursos compartilhados capazes de influenciar o funcionamento legalmente relevante, bem como os respectivos mecanismos de controle. Quando o processo de inicialização puder influenciar o software legalmente relevante, devem ser documentados o processo e a configuração de inicialização, as fontes e interfaces pelas quais a inicialização possa ocorrer e os mecanismos utilizados para impedir a execução de software ou configurações não admissíveis."}, {"c": "dou-paragraph", "t": "3.10.9 Outras informações técnicas necessárias à compreensão da arquitetura ou à avaliação do atendimento aos requisitos específicos aplicáveis podem ser solicitadas."}, {"c": "dou-paragraph", "t": "4. Disposições Gerais"}, {"c": "dou-paragraph", "t": "4.1 Avaliação de modelo"}, {"c": "dou-paragraph", "t": "4.1.1 Os requisitos deste Anexo aplicam-se às funções, componentes e arquiteturas efetivamente presentes no modelo do instrumento submetido à avaliação."}, {"c": "dou-paragraph", "t": "4.1.2 Os requisitos gerais da seção 2 aplicam-se a todo instrumento controlado por software, independentemente da tecnologia utilizada em sua implementação."}, {"c": "dou-paragraph", "t": "4.1.3 Os requisitos específicos da seção 3 aplicam-se somente quando o instrumento possuir a funcionalidade ou arquitetura correspondente."}, {"c": "dou-paragraph", "t": "4.1.4 A delimitação dos componentes de software e hardware legalmente relevantes apresentada pelo requerente está sujeita à avaliação do Inmetro, que poderá determinar a inclusão de outros componentes quando sua alteração ou funcionamento puder exercer influência inadmissível sobre funções, dados, parâmetros ou resultados legalmente relevantes."}, {"c": "dou-paragraph", "t": "4.1.5 Somente versões do software legalmente relevante previamente avaliadas e aprovadas pelo Inmetro podem ser instaladas no instrumento para utilização legalmente relevante."}, {"c": "dou-paragraph", "t": "4.1.6 Para fins de avaliação de modelo, soluções técnicas possíveis e aceitáveis para o cumprimento dos requisitos deste Regulamento podem ser descritas em Norma Inmetro específica (NIT-Sinst-0xx)."}, {"c": "dou-paragraph", "t": "4.1.7 A utilização de determinada solução técnica proposta em Norma Inmetro específica não impede a utilização de solução tecnologicamente equivalente, desde que sua conformidade com os requisitos deste Anexo seja demonstrada durante a avaliação de modelo."}, {"c": "dou-paragraph", "t": "4.1.8 Os métodos, procedimentos de ensaio e critérios técnicos para demonstração do atendimento aos requisitos deste Anexo podem ser estabelecidos em Norma Inmetro específica (NIT-Sinst-0xx)."}, {"c": "dou-paragraph", "t": "4.1.9 O requerente do processo de avaliação de modelo deve disponibilizar os meios, equipamentos, ferramentas e informações necessários à execução dos ensaios, exames e verificações previstos para demonstração do atendimento aos requisitos deste Anexo, incluindo, quando aplicáveis, dispositivos acessórios do instrumento, cabos e adaptadores para conexão, meios para simulação da medição em laboratório e ferramentas de software ou hardware necessárias à configuração, atualização e verificação do instrumento."}, {"c": "dou-paragraph", "t": "4.2 Disponibilidade e análise do código-fonte"}, {"c": "dou-paragraph", "t": "4.2.1 A disponibilização integral e prévia do código-fonte do software legalmente relevante não constitui requisito obrigatório para a aprovação de modelo."}, {"c": "dou-paragraph", "t": "4.2.2 O requerente deve manter disponível o código-fonte correspondente ao software legalmente relevante submetido à aprovação de modelo, de forma organizada e em condições que permitam sua análise quando esta for necessária à avaliação do atendimento aos requisitos deste Regulamento."}, {"c": "dou-paragraph", "t": "4.2.3 O Inmetro poderá solicitar a disponibilização do código-fonte, total ou parcial, quando sua análise for necessária à avaliação do atendimento aos requisitos aplicáveis."}, {"c": "dou-paragraph", "t": "4.2.4 A extensão do código-fonte a ser disponibilizado deve ser limitada às partes necessárias à avaliação, podendo compreender módulos, funções, rotinas, bibliotecas ou outros componentes específicos do software legalmente relevante."}, {"c": "dou-paragraph", "t": "4.2.5 Quando tecnicamente suficiente para a finalidade da avaliação, a análise do código-fonte poderá ser complementada ou substituída por outras evidências técnicas capazes de demonstrar o atendimento aos requisitos aplicáveis."}, {"c": "dou-paragraph", "t": "4.2.6 O código-fonte disponibilizado para avaliação deve corresponder inequivocamente ao software legalmente relevante objeto da aprovação de modelo."}, {"c": "dou-paragraph", "t": "4.2.7 Deve ser possível estabelecer a correspondência entre o código-fonte disponibilizado para avaliação, o software legalmente relevante aprovado e o software instalado no instrumento, por meio de identificação e de mecanismos adequados de verificação de integridade."}, {"c": "dou-paragraph", "t": "4.2.8 O código-fonte e as demais informações técnicas de caráter confidencial disponibilizados para avaliação devem ser tratados de forma a preservar sua confidencialidade e utilizados exclusivamente para as finalidades relacionadas à avaliação e ao controle metrológico legal, observadas as disposições legais e administrativas aplicáveis."}, {"c": "dou-paragraph", "t": "4.2.9 Os procedimentos para disponibilização, acesso, custódia, análise e proteção do código-fonte, bem como os critérios para utilização de evidências técnicas alternativas ou complementares, podem ser estabelecidos em Norma Inmetro específica (NIT-Sinst-0xx)."}]});